-- Shipping Times 테스트 데이터 (Supabase SQL 에디터에서 실행: seed-shipping-times.sql·market-indices.sql 다음)
--   1) 섹션마다 가상 기사 20건, 모두 160건 — 제목에 [테스트], 본문 끝에 “가상 기사” 안내가 붙는다
--      실제 기사를 옮긴 것이 아니라 테스트용으로 새로 쓴 글이며, 회사·인물 이름은 넣지 않았다 (A선사, B포워딩 등)
--   2) 해운 운임지수(SCFI·KCCI) 샘플 12주 — 홈페이지에 “샘플” 표시가 붙는다 (실제 지수 아님)
--   3) Shipping Times 홈페이지에 운임지수 위젯을 켠다
--   여러 번 실행해도 같은 기사·같은 주 값은 다시 넣지 않는다
--
--   정식 오픈 전 지우기:
--     delete from articles a using outlets o where a.outlet_id = o.id and o.name = 'Shipping Times' and a.title like '[테스트]%';
--     delete from market_index_points p using outlets o where p.outlet_id = o.id and o.name = 'Shipping Times' and p.is_sample;

-- 3) 위젯 켜기
update outlets set site = coalesce(site, '{}'::jsonb) || '{"indexWidget": true}'::jsonb where name = 'Shipping Times';

-- 1) 가상 기사
with ctx as (
  select o.id as outlet_id,
         coalesce(
           (select p.id from profiles p where p.outlet_id = o.id and p.role in ('admin', 'editor') order by p.created_at limit 1),
           (select p.id from profiles p where p.is_super order by p.created_at limit 1)
         ) as author_id
  from outlets o
  where o.name = 'Shipping Times'
)
insert into articles (outlet_id, category_id, author_id, byline, title, body, excerpt, thumbnail_url, status, published_at, is_featured, tags)
select ctx.outlet_id, c.id, ctx.author_id, '편집국', v.title, v.body, v.excerpt, v.thumb, 'published', v.published_at, v.featured, array['테스트']
from ctx
cross join (values
  ('shipping', '[테스트] 상하이컨테이너운임지수 3주 연속 상승…아시아-유럽 항로 강세', '<p>상하이컨테이너운임지수(SCFI)가 3주 연속 오르며 1,980포인트선에 근접한 것으로 집계됐다. 아시아-유럽 항로와 지중해 항로 운임이 동반 상승하면서 전체 지수 상승세를 이끈 것으로 나타났으며, 업계는 당분간 강세가 이어질 가능성에 무게를 두고 있다.</p><p>업계에 따르면 유럽 항로 운임은 전주 대비 6.4% 오른 TEU당 1,720달러를 기록했다. 한 국적선사 영업 담당자는 “성수기 할증료 적용과 선복 조정이 겹치면서 운임이 탄력을 받았다”며 “다음 달 초까지는 강보합세가 이어질 것”이라고 내다봤다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '상하이컨테이너운임지수(SCFI)가 3주 연속 오르며 1,980포인트선에 근접한 것으로 집계됐다. 아시아-유럽 항로와 지중해 항로 운임이 동반 상승하면서 전체 지수 상승세를 이끈 것으로 나타났으며, 업계는 당분간 강세가 이어질 가능성에 무게를 두고 있다.', 'https://picsum.photos/seed/ship-shipping-0/800/500', '2026-10-02 09:00:00+09'::timestamptz, true),
  ('shipping', '[테스트] 국내 A선사, 메탄올 추진 컨테이너선 6척 발주…친환경 선대 전환 가속', '<p>국내 A선사가 1만3천TEU급 메탄올 이중연료 추진 컨테이너선 6척을 국내 조선소에 발주했다고 밝혔다. 총 투자 규모는 약 1조4천억원으로, 선박은 오는 2029년까지 순차적으로 인도돼 주력 원양 항로에 배치될 예정이다.</p><p>A선사는 신조선을 아시아-유럽 및 아시아-지중해 항로에 투입해 탄소 배출량을 기존 선박 대비 최대 60%가량 줄인다는 계획이다. 회사 관계자는 “강화되는 국제 환경규제에 선제적으로 대응하고 화주의 탈탄소 요구에 부응하기 위한 결정”이라고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 A선사가 1만3천TEU급 메탄올 이중연료 추진 컨테이너선 6척을 국내 조선소에 발주했다고 밝혔다. 총 투자 규모는 약 1조4천억원으로, 선박은 오는 2029년까지 순차적으로 인도돼 주력 원양 항로에 배치될 예정이다.', 'https://picsum.photos/seed/ship-shipping-1/800/500', '2026-09-30 10:43:00+09'::timestamptz, true),
  ('shipping', '[테스트] 선사들 블랭크세일링 확대…아시아-북유럽 선복 공급 조정 본격화', '<p>아시아-북유럽 항로를 운항하는 주요 선사들이 다음 달 결항(블랭크세일링) 일정을 잇달아 공지하며 선복 공급 조정에 나섰다. 업계는 이번 조치로 해당 항로의 주간 공급량이 약 8% 줄어들 것으로 보고 있다.</p><p>시장에서는 신조선 인도가 이어지는 가운데 선사들이 운임 하락을 방어하기 위한 전략으로 해석하고 있다. 한 해운 분석가는 “비수기 진입을 앞두고 공급을 선제적으로 줄이려는 움직임”이라며 “실제 운임 방어 효과는 화물 수요 회복 속도에 달려 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '아시아-북유럽 항로를 운항하는 주요 선사들이 다음 달 결항(블랭크세일링) 일정을 잇달아 공지하며 선복 공급 조정에 나섰다. 업계는 이번 조치로 해당 항로의 주간 공급량이 약 8% 줄어들 것으로 보고 있다.', 'https://picsum.photos/seed/ship-shipping-2/800/500', '2026-09-28 12:26:00+09'::timestamptz, false),
  ('shipping', '[테스트] 홍해 우회 운항 장기화…희망봉 경유 항로 정착 단계', '<p>홍해 항로 대신 아프리카 남단 희망봉을 경유하는 운항이 장기화하면서 선사들의 항로 운영이 사실상 새로운 체계로 자리 잡고 있다. 아시아-유럽 간 평균 항해일수는 기존보다 10일 안팎 늘어난 상태로, 선사들은 이에 맞춘 운항 계획을 짜고 있다.</p><p>업계에 따르면 주요 선사들은 늘어난 항해일수에 맞춰 투입 선박 수를 항로당 1~2척씩 추가 배치했다. B해운 관계자는 “수에즈 통항 재개 시점이 불투명한 만큼 현 체제를 전제로 연간 운항 계획을 세우고 있다”고 전했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '홍해 항로 대신 아프리카 남단 희망봉을 경유하는 운항이 장기화하면서 선사들의 항로 운영이 사실상 새로운 체계로 자리 잡고 있다. 아시아-유럽 간 평균 항해일수는 기존보다 10일 안팎 늘어난 상태로, 선사들은 이에 맞춘 운항 계획을 짜고 있다.', 'https://picsum.photos/seed/ship-shipping-3/800/500', '2026-09-26 14:09:00+09'::timestamptz, false),
  ('shipping', '[테스트] 건화물선 운임지수 반등…케이프사이즈 철광석 수요 회복', '<p>건화물선 시황을 나타내는 발틱운임지수(BDI)가 2주 만에 반등하며 1,850포인트를 회복한 것으로 나타났다. 대형 벌크선인 케이프사이즈 선형의 철광석 운송 수요가 늘어난 것이 상승을 이끌었으며, 중소형 선형 운임도 소폭 오름세를 보였다.</p><p>케이프사이즈 일일 용선료는 전주 대비 12% 오른 2만4천달러 수준까지 올라섰다. 국내 C벌크 관계자는 “남미와 호주발 철광석 선적이 동시에 늘면서 선박 수급이 빠듯해졌다”며 “곡물 수확기와 맞물려 당분간 견조한 흐름이 예상된다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '건화물선 시황을 나타내는 발틱운임지수(BDI)가 2주 만에 반등하며 1,850포인트를 회복한 것으로 나타났다. 대형 벌크선인 케이프사이즈 선형의 철광석 운송 수요가 늘어난 것이 상승을 이끌었으며, 중소형 선형 운임도 소폭 오름세를 보였다.', null, '2026-09-24 16:52:00+09'::timestamptz, false),
  ('shipping', '[테스트] 초대형유조선 운임 강세 지속…중동-아시아 항로 용선 경쟁', '<p>원유를 실어 나르는 초대형유조선(VLCC) 운임이 한 달째 강세를 이어가고 있다. 중동에서 아시아로 향하는 원유 물동량이 늘어난 가운데 가용 선박이 제한되면서 선박 확보 경쟁이 치열해진 영향으로 풀이되며, 선주들의 수익성도 크게 개선됐다.</p><p>업계에 따르면 중동-동북아 VLCC 항로의 일일 수익은 최근 5만달러를 웃돌며 연중 최고 수준을 기록했다. 한 탱커 선사 관계자는 “노후선 해체로 가용 선복이 줄어든 반면 신조선 인도는 제한적이어서 수급 여건이 선주에게 유리하게 형성돼 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '원유를 실어 나르는 초대형유조선(VLCC) 운임이 한 달째 강세를 이어가고 있다. 중동에서 아시아로 향하는 원유 물동량이 늘어난 가운데 가용 선박이 제한되면서 선박 확보 경쟁이 치열해진 영향으로 풀이되며, 선주들의 수익성도 크게 개선됐다.', 'https://picsum.photos/seed/ship-shipping-5/800/500', '2026-09-22 18:35:00+09'::timestamptz, false),
  ('shipping', '[테스트] 미주 서안 항로 장기운송계약 협상 앞두고 선사-화주 눈치싸움', '<p>내년도 미주 서안 항로 장기운송계약(SC) 협상을 앞두고 선사와 대형 화주 간 신경전이 본격적으로 시작됐다. 현물 운임이 약세를 보이는 가운데 선사들은 계약 운임을 일정 수준 이상으로 유지하려는 입장이어서 협상이 길어질 가능성이 제기된다.</p><p>한 대형 유통 화주 물류 담당자는 “현물 시장과 계약 운임 간 격차가 커져 인하 요구가 불가피하다”고 말했다. 반면 D선사 관계자는 “안정적 선복 제공에 대한 가치를 인정받아야 한다”며 “물량 보장 조건에 따라 유연하게 접근할 것”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '내년도 미주 서안 항로 장기운송계약(SC) 협상을 앞두고 선사와 대형 화주 간 신경전이 본격적으로 시작됐다. 현물 운임이 약세를 보이는 가운데 선사들은 계약 운임을 일정 수준 이상으로 유지하려는 입장이어서 협상이 길어질 가능성이 제기된다.', 'https://picsum.photos/seed/ship-shipping-6/800/500', '2026-09-20 20:18:00+09'::timestamptz, false),
  ('shipping', '[테스트] 한국형컨테이너운임지수 소폭 하락…동남아 항로 약세 영향', '<p>한국형컨테이너운임지수(KCCI)가 전주 대비 2.1% 하락한 2,140포인트를 기록하며 2주 연속 내림세를 보였다. 부산발 동남아 항로 운임이 약세를 보이면서 전체 지수를 끌어내린 것으로 분석되며, 원양 항로는 상대적으로 견조한 흐름을 유지했다.</p><p>항로별로는 부산-호찌민 운임이 7% 넘게 떨어졌고, 부산-로테르담 운임은 소폭 상승했다. 업계 관계자는 “근해 항로에 신규 선사 진입이 이어지며 공급이 늘어난 상황”이라며 “원양 항로와 근해 항로의 온도 차가 당분간 지속될 것”이라고 전망했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '한국형컨테이너운임지수(KCCI)가 전주 대비 2.1% 하락한 2,140포인트를 기록하며 2주 연속 내림세를 보였다. 부산발 동남아 항로 운임이 약세를 보이면서 전체 지수를 끌어내린 것으로 분석되며, 원양 항로는 상대적으로 견조한 흐름을 유지했다.', 'https://picsum.photos/seed/ship-shipping-7/800/500', '2026-09-18 22:01:00+09'::timestamptz, false),
  ('shipping', '[테스트] 부산항 신항 환적 물동량 역대 최대…허브 경쟁력 부각', '<p>부산항 신항의 3분기 환적 물동량이 전년 동기 대비 9% 늘어나며 분기 기준 역대 최대치를 기록한 것으로 집계됐다. 북중국과 일본 지방항을 연결하는 환적 수요가 꾸준히 증가한 결과로, 동북아 허브 항만으로서의 위상이 한층 높아졌다는 평가다.</p><p>업계에 따르면 신항 내 자동화 터미널의 하역 생산성이 개선되면서 선사들의 기항 선호도가 높아졌다. 한 터미널 운영사 관계자는 “선석 대기시간이 크게 줄어 환적 연결성이 좋아졌다”며 “추가 선석 개장이 완료되면 처리 여력이 더 확대될 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '부산항 신항의 3분기 환적 물동량이 전년 동기 대비 9% 늘어나며 분기 기준 역대 최대치를 기록한 것으로 집계됐다. 북중국과 일본 지방항을 연결하는 환적 수요가 꾸준히 증가한 결과로, 동북아 허브 항만으로서의 위상이 한층 높아졌다는 평가다.', 'https://picsum.photos/seed/ship-shipping-8/800/500', '2026-09-17 00:44:00+09'::timestamptz, false),
  ('shipping', '[테스트] 글로벌 해운동맹 재편 1년…정시성 지표 개선 뚜렷', '<p>주요 글로벌 선사들의 해운동맹(얼라이언스) 재편이 이뤄진 지 1년이 지나면서 서비스 품질 지표가 뚜렷하게 개선되고 있다. 특히 허브 앤 스포크 방식을 도입한 동맹의 정시성이 크게 높아지면서 화주들의 선사 선택 기준에도 변화가 나타나고 있다.</p><p>업계 집계에 따르면 일부 동맹의 월평균 정시 도착률은 80%를 넘어섰다. 글로벌 E해운 관계자는 “기항지를 줄이고 핵심 허브에 집중한 전략이 효과를 냈다”며 “화주들도 운임보다 일정 신뢰도를 중시하는 경향이 강해지고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '주요 글로벌 선사들의 해운동맹(얼라이언스) 재편이 이뤄진 지 1년이 지나면서 서비스 품질 지표가 뚜렷하게 개선되고 있다. 특히 허브 앤 스포크 방식을 도입한 동맹의 정시성이 크게 높아지면서 화주들의 선사 선택 기준에도 변화가 나타나고 있다.', null, '2026-09-15 02:27:00+09'::timestamptz, false),
  ('shipping', '[테스트] 동남아 항로 선복 과잉 우려…중소 선사 서비스 통폐합 검토', '<p>한국과 동남아를 잇는 근해 항로에서 선복 과잉 우려가 커지면서 중소 선사들이 서비스 통폐합을 검토하고 있는 것으로 알려졌다. 최근 1년간 이 항로의 주간 공급량은 15% 가까이 늘어난 것으로 추정되며, 운임 하락 압력도 함께 커지고 있다.</p><p>업계에 따르면 일부 선사는 공동운항(VSA) 확대를 통해 선박 투입 수를 줄이는 방안을 협의 중이다. F해운 관계자는 “개별 운항으로는 소석률을 유지하기 어려운 구간이 늘고 있다”며 “협력 모델을 통해 효율을 높이는 것이 현실적 대안”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '한국과 동남아를 잇는 근해 항로에서 선복 과잉 우려가 커지면서 중소 선사들이 서비스 통폐합을 검토하고 있는 것으로 알려졌다. 최근 1년간 이 항로의 주간 공급량은 15% 가까이 늘어난 것으로 추정되며, 운임 하락 압력도 함께 커지고 있다.', 'https://picsum.photos/seed/ship-shipping-10/800/500', '2026-09-13 04:10:00+09'::timestamptz, false),
  ('shipping', '[테스트] LNG운반선 단기 용선료 하락…신조선 대거 인도 영향', '<p>액화천연가스(LNG) 운반선의 단기 용선료가 3개월째 하락세를 이어가고 있다. 올해 들어 신조 LNG선 인도가 집중되면서 시장에 투입 가능한 선박이 크게 늘어난 데 따른 것으로, 장기 용선 시장과 단기 시장 간 온도 차가 커지는 모습이다.</p><p>업계에 따르면 17만4천㎥급 LNG선의 스팟 용선료는 하루 3만달러대로 내려앉았다. 한 가스선 업계 관계자는 “장기 계약 물량은 안정적이지만 단기 시장은 공급 부담이 크다”며 “동절기 수요가 본격화되는 연말께 반등 여부가 판가름 날 것”이라고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '액화천연가스(LNG) 운반선의 단기 용선료가 3개월째 하락세를 이어가고 있다. 올해 들어 신조 LNG선 인도가 집중되면서 시장에 투입 가능한 선박이 크게 늘어난 데 따른 것으로, 장기 용선 시장과 단기 시장 간 온도 차가 커지는 모습이다.', 'https://picsum.photos/seed/ship-shipping-11/800/500', '2026-09-11 06:53:00+09'::timestamptz, false),
  ('shipping', '[테스트] 자동차운반선 수요 견조…국내 G해운 신조 PCTC 투입', '<p>완성차 수출 호조가 이어지면서 자동차운반선(PCTC) 수요가 견조한 흐름을 보이고 있다. 국내 G해운은 7천대급 신조 자동차운반선을 이달 중 유럽 항로에 처음 투입한다고 밝혔으며, 연내 같은 선형 1척을 추가로 인도받을 예정이다.</p><p>신조선은 액화천연가스를 연료로 사용하며, 전기차 적재를 고려해 데크 하중과 화재 대응 설비를 강화했다. G해운 관계자는 “친환경차 수출 비중이 늘면서 화주들의 선박 사양 요구도 까다로워지고 있다”며 “선대 현대화를 지속할 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '완성차 수출 호조가 이어지면서 자동차운반선(PCTC) 수요가 견조한 흐름을 보이고 있다. 국내 G해운은 7천대급 신조 자동차운반선을 이달 중 유럽 항로에 처음 투입한다고 밝혔으며, 연내 같은 선형 1척을 추가로 인도받을 예정이다.', 'https://picsum.photos/seed/ship-shipping-12/800/500', '2026-09-09 08:36:00+09'::timestamptz, false),
  ('shipping', '[테스트] 해운 탄소규제 본격화 앞두고 선사들 연료 전략 고심', '<p>국제 해운업계의 탄소 배출 규제가 단계적으로 강화되면서 선사들의 연료 전략 고민이 깊어지고 있다. 메탄올과 암모니아, LNG 등 대체연료를 놓고 선사별 선택이 엇갈리는 가운데 신조선 발주 사양에도 이 같은 고민이 고스란히 반영되는 양상이다.</p><p>업계에 따르면 대체연료의 가격과 공급망이 아직 불확실해 이중연료 엔진을 채택하는 사례가 늘고 있다. H해운 기술 담당 임원은 “특정 연료에 올인하기보다 전환 유연성을 확보하는 것이 핵심”이라며 “벙커링 인프라 확충 속도가 변수가 될 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국제 해운업계의 탄소 배출 규제가 단계적으로 강화되면서 선사들의 연료 전략 고민이 깊어지고 있다. 메탄올과 암모니아, LNG 등 대체연료를 놓고 선사별 선택이 엇갈리는 가운데 신조선 발주 사양에도 이 같은 고민이 고스란히 반영되는 양상이다.', 'https://picsum.photos/seed/ship-shipping-13/800/500', '2026-09-07 10:19:00+09'::timestamptz, false),
  ('shipping', '[테스트] 전자선하증권 도입 확산…선사·화주 서류 처리 시간 단축', '<p>종이 서류 대신 전자선하증권(e-B/L)을 활용하는 사례가 선사와 화주를 중심으로 빠르게 늘고 있다. 업계에서는 전자 방식 도입으로 서류 처리 시간이 기존 대비 최대 70%가량 단축되고 관련 비용도 크게 줄어든 것으로 보고 있다.</p><p>국내 I선사는 올해 전체 발행 선하증권 가운데 전자 방식 비중이 25%를 넘어섰다고 밝혔다. 회사 관계자는 “분실 위험이 줄고 대금 결제 흐름도 빨라져 화주 만족도가 높다”며 “금융기관과의 연계 표준이 정착되면 확산 속도가 더 붙을 것”이라고 전망했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '종이 서류 대신 전자선하증권(e-B/L)을 활용하는 사례가 선사와 화주를 중심으로 빠르게 늘고 있다. 업계에서는 전자 방식 도입으로 서류 처리 시간이 기존 대비 최대 70%가량 단축되고 관련 비용도 크게 줄어든 것으로 보고 있다.', null, '2026-09-05 12:02:00+09'::timestamptz, false),
  ('shipping', '[테스트] “선대 규모보다 수익 구조”…J해운 대표가 말하는 중장기 전략', '<p>J해운 대표는 최근 본지 기자와 만나 향후 5년간 선대 확장보다 항로 포트폴리오 재편에 집중하겠다고 밝혔다. 운임 변동성이 커진 시장 환경에서 외형 성장보다 안정적인 수익 구조를 만드는 것이 우선이라는 설명이다.</p><p>그는 “원양과 근해, 냉동화물과 특수화물을 균형 있게 배분해 특정 항로 의존도를 낮추겠다”고 말했다. 이어 “디지털 예약 시스템과 고객 데이터 분석에도 투자를 늘려 화주와의 장기 관계를 강화하는 데 역량을 모을 것”이라고 강조했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'J해운 대표는 최근 본지 기자와 만나 향후 5년간 선대 확장보다 항로 포트폴리오 재편에 집중하겠다고 밝혔다. 운임 변동성이 커진 시장 환경에서 외형 성장보다 안정적인 수익 구조를 만드는 것이 우선이라는 설명이다.', 'https://picsum.photos/seed/ship-shipping-15/800/500', '2026-09-03 14:45:00+09'::timestamptz, false),
  ('shipping', '[테스트] 컨테이너선 발주잔량 선대 대비 30% 육박…공급 부담 커져', '<p>전 세계 컨테이너선 발주잔량이 현존 선대 대비 30%에 육박하는 수준까지 늘어난 것으로 나타났다. 향후 2~3년간 신조선 인도가 집중될 예정이어서 시장의 공급 부담이 커지고 운임 하방 압력도 높아질 것이라는 관측이 나온다.</p><p>업계 분석에 따르면 발주잔량의 절반 이상이 1만5천TEU급 이상 초대형선에 집중돼 있다. 한 해운 연구 관계자는 “노후선 해체가 얼마나 빠르게 진행되느냐가 수급 균형의 관건”이라며 “선사들의 공급 관리 능력이 수익성을 좌우할 것”이라고 분석했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '전 세계 컨테이너선 발주잔량이 현존 선대 대비 30%에 육박하는 수준까지 늘어난 것으로 나타났다. 향후 2~3년간 신조선 인도가 집중될 예정이어서 시장의 공급 부담이 커지고 운임 하방 압력도 높아질 것이라는 관측이 나온다.', 'https://picsum.photos/seed/ship-shipping-16/800/500', '2026-09-01 16:28:00+09'::timestamptz, false),
  ('shipping', '[테스트] 한-일 근해 항로 물동량 회복세…지방항 직기항 서비스 확대', '<p>한국과 일본을 잇는 근해 컨테이너 항로의 물동량이 회복세를 보이고 있다. 국내 K해운은 이 같은 수요 증가에 대응해 일본 지방항 3곳을 추가로 연결하는 직기항 서비스를 다음 달부터 새로 개설한다고 밝혔다.</p><p>신규 서비스는 부산항을 거점으로 주 2회 운항하며, 소형 피더선 2척이 투입된다. K해운 관계자는 “일본 지방 제조업체들의 부산항 환적 수요가 꾸준히 늘고 있다”며 “운송 시간을 하루 이상 줄여 경쟁력을 확보할 것”이라고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '한국과 일본을 잇는 근해 컨테이너 항로의 물동량이 회복세를 보이고 있다. 국내 K해운은 이 같은 수요 증가에 대응해 일본 지방항 3곳을 추가로 연결하는 직기항 서비스를 다음 달부터 새로 개설한다고 밝혔다.', 'https://picsum.photos/seed/ship-shipping-17/800/500', '2026-08-30 18:11:00+09'::timestamptz, false),
  ('shipping', '[테스트] 냉동컨테이너 운임 상승…남미발 과일 수출 성수기 진입', '<p>남미발 신선 과일 수출 성수기가 시작되면서 냉동컨테이너(리퍼) 운임이 오름세를 보이고 있다. 남미 서안에서 아시아로 향하는 리퍼 운임은 한 달 새 10% 넘게 상승한 것으로 파악됐으며, 장비 수급도 점차 빠듯해지는 분위기다.</p><p>업계에 따르면 리퍼 장비 회수가 늦어지면서 일부 지역에서는 빈 컨테이너 수급에 어려움을 겪고 있다. L선사 관계자는 “성수기 물량에 대비해 장비를 사전 배치했지만 수요가 예상보다 빠르게 늘고 있다”며 “장비 회전율 관리에 집중하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '남미발 신선 과일 수출 성수기가 시작되면서 냉동컨테이너(리퍼) 운임이 오름세를 보이고 있다. 남미 서안에서 아시아로 향하는 리퍼 운임은 한 달 새 10% 넘게 상승한 것으로 파악됐으며, 장비 수급도 점차 빠듯해지는 분위기다.', 'https://picsum.photos/seed/ship-shipping-18/800/500', '2026-08-28 20:54:00+09'::timestamptz, false),
  ('shipping', '[테스트] 중고 컨테이너선 가격 조정 국면…선주들 매각 시점 저울질', '<p>중고 컨테이너선 가격이 고점 대비 조정 국면에 접어들면서 선주들이 매각 시점을 저울질하고 있다. 선령 10년 안팎의 중형 선박을 중심으로 거래 가격이 완만하게 하락하는 추세이며, 실제 거래 건수도 전년보다 다소 줄어든 것으로 나타났다.</p><p>업계에 따르면 4천TEU급 10년 된 선박의 거래 가격은 연초 대비 약 12% 낮아졌다. 한 선박 중개업체 관계자는 “용선 시장이 여전히 견조해 급매물은 많지 않다”며 “매수자와 매도자 간 가격 눈높이 차이로 거래 성사까지 시간이 길어지고 있다”고 전했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '중고 컨테이너선 가격이 고점 대비 조정 국면에 접어들면서 선주들이 매각 시점을 저울질하고 있다. 선령 10년 안팎의 중형 선박을 중심으로 거래 가격이 완만하게 하락하는 추세이며, 실제 거래 건수도 전년보다 다소 줄어든 것으로 나타났다.', null, '2026-08-26 22:37:00+09'::timestamptz, false),
  ('logistics', '[테스트] 이커머스 물류 수요 급증…A풀필먼트, 수도권 대형 센터 2곳 추가', '<p>이커머스 물동량이 꾸준히 늘면서 A풀필먼트가 수도권에 연면적 합계 12만㎡ 규모의 물류센터 2곳을 추가로 개장한다고 밝혔다. 이번 확장으로 회사의 일일 출고 처리 능력은 기존보다 약 40% 늘어날 전망이다.</p><p>신규 센터에는 자동 분류기와 상품 보관 로봇이 도입돼 주문 처리 시간이 크게 단축될 것으로 예상된다. A풀필먼트 관계자는 “중소 판매자들의 입점 문의가 빠르게 늘고 있다”며 “당일 출고 마감 시간을 늦춰 판매자 경쟁력을 높이겠다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '이커머스 물동량이 꾸준히 늘면서 A풀필먼트가 수도권에 연면적 합계 12만㎡ 규모의 물류센터 2곳을 추가로 개장한다고 밝혔다. 이번 확장으로 회사의 일일 출고 처리 능력은 기존보다 약 40% 늘어날 전망이다.', 'https://picsum.photos/seed/ship-logistics-0/800/500', '2026-10-02 03:53:00+09'::timestamptz, true),
  ('logistics', '[테스트] AI 배차 플랫폼 도입 확산…공차율 낮추고 운송비 절감', '<p>인공지능(AI) 기반 화물 배차 플랫폼을 도입하는 운송사가 늘면서 업계의 공차 운행 비율이 눈에 띄게 낮아지고 있다. 국내 B물류는 자체 AI 배차 시스템 도입 이후 공차율을 기존 대비 30% 가까이 줄였다고 밝혔다.</p><p>이 시스템은 실시간 교통 정보와 화물 데이터를 분석해 최적의 차량과 경로를 자동으로 배정한다. B물류 관계자는 “차주들의 대기 시간이 줄면서 운행 효율과 수입이 함께 개선됐다”며 “내년에는 외부 운송사에도 플랫폼을 개방할 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '인공지능(AI) 기반 화물 배차 플랫폼을 도입하는 운송사가 늘면서 업계의 공차 운행 비율이 눈에 띄게 낮아지고 있다. 국내 B물류는 자체 AI 배차 시스템 도입 이후 공차율을 기존 대비 30% 가까이 줄였다고 밝혔다.', 'https://picsum.photos/seed/ship-logistics-1/800/500', '2026-09-30 05:36:00+09'::timestamptz, true),
  ('logistics', '[테스트] C포워딩, 미주행 항공화물 전세기 정기 운영…성수기 수요 대응', '<p>C포워딩이 연말 성수기를 앞두고 인천-미주 구간 화물 전세기를 주 3회 정기 운영한다고 밝혔다. 반도체 장비와 이커머스 화물 수요가 동시에 늘어나면서 정기 여객기 화물칸만으로는 공간 확보가 어려워진 데 따른 대응이다.</p><p>C포워딩은 전세기 운영을 통해 고객사에 고정 운임과 안정적인 적재 공간을 제공한다는 계획이다. 회사 관계자는 “성수기에는 정기편 화물칸 확보가 어려워 고객 불편이 컸다”며 “사전 예약 물량이 이미 공급량의 70%를 넘어섰다”고 전했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'C포워딩이 연말 성수기를 앞두고 인천-미주 구간 화물 전세기를 주 3회 정기 운영한다고 밝혔다. 반도체 장비와 이커머스 화물 수요가 동시에 늘어나면서 정기 여객기 화물칸만으로는 공간 확보가 어려워진 데 따른 대응이다.', 'https://picsum.photos/seed/ship-logistics-2/800/500', '2026-09-28 07:19:00+09'::timestamptz, false),
  ('logistics', '[테스트] 의약품 콜드체인 시장 성장…온도 관리 인증 센터 확충 경쟁', '<p>바이오 의약품 수출이 늘면서 의약품 전용 콜드체인 물류 시장이 빠르게 성장하고 있다. 물류업체들은 의약품 유통 품질 기준을 충족하는 온도 관리 센터를 앞다퉈 확충하며 고부가가치 화물 유치 경쟁에 나서는 모습이다.</p><p>국내 D로지스는 영하 70도 초저온 보관 설비를 갖춘 의약품 전용 센터를 연내 가동한다고 밝혔다. 회사 관계자는 “운송 전 구간의 온도 데이터를 실시간 기록해 화주에게 제공하는 것이 경쟁력의 핵심”이라며 “항공 운송사와의 연계도 강화할 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '바이오 의약품 수출이 늘면서 의약품 전용 콜드체인 물류 시장이 빠르게 성장하고 있다. 물류업체들은 의약품 유통 품질 기준을 충족하는 온도 관리 센터를 앞다퉈 확충하며 고부가가치 화물 유치 경쟁에 나서는 모습이다.', null, '2026-09-26 09:02:00+09'::timestamptz, false),
  ('logistics', '[테스트] 3PL 계약 구조 변화…단순 위탁서 성과공유형으로 이동', '<p>제조·유통 기업과 3자물류(3PL) 업체 간 계약 구조가 단순 위탁 방식에서 성과공유형으로 바뀌고 있다. 물류비 절감 성과를 일정 비율로 나누는 방식이 확산되면서 양측의 협력 관계도 장기화하는 추세다.</p><p>업계에 따르면 최근 신규 3PL 계약의 상당수가 3년 이상 장기 계약에 성과 지표를 연동하는 형태로 체결되고 있다. E물류 영업 담당 임원은 “고객사 공급망 전반을 함께 설계하는 파트너 역할이 요구되고 있다”며 “데이터 공유가 신뢰의 전제”라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '제조·유통 기업과 3자물류(3PL) 업체 간 계약 구조가 단순 위탁 방식에서 성과공유형으로 바뀌고 있다. 물류비 절감 성과를 일정 비율로 나누는 방식이 확산되면서 양측의 협력 관계도 장기화하는 추세다.', 'https://picsum.photos/seed/ship-logistics-4/800/500', '2026-09-24 11:45:00+09'::timestamptz, false),
  ('logistics', '[테스트] 수도권 물류센터 공실률 하락 전환…임대 시장 안정세', '<p>공급 과잉 우려가 컸던 수도권 물류센터 임대 시장이 점차 안정세를 되찾고 있다. 업계에 따르면 3분기 수도권 대형 물류센터의 평균 공실률은 전 분기보다 2%포인트가량 하락한 것으로 나타나 2개 분기 연속 개선 흐름을 이어갔다.</p><p>신규 공급이 줄어든 가운데 이커머스와 3PL 업체들의 임차 수요가 꾸준히 유입된 결과다. 한 물류 부동산 자문사 관계자는 “상온 센터를 중심으로 임차 문의가 늘고 있다”며 “저온 센터는 지역별 편차가 있어 선별적 접근이 필요하다”고 분석했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '공급 과잉 우려가 컸던 수도권 물류센터 임대 시장이 점차 안정세를 되찾고 있다. 업계에 따르면 3분기 수도권 대형 물류센터의 평균 공실률은 전 분기보다 2%포인트가량 하락한 것으로 나타나 2개 분기 연속 개선 흐름을 이어갔다.', 'https://picsum.photos/seed/ship-logistics-5/800/500', '2026-09-22 13:28:00+09'::timestamptz, false),
  ('logistics', '[테스트] 역직구 물류 서비스 경쟁 가열…해외 배송 리드타임 단축 총력', '<p>국내 상품을 해외 소비자에게 판매하는 역직구 시장이 커지면서 관련 물류 서비스 경쟁이 치열해지고 있다. 물류업체들은 현지 배송망 제휴와 통관 자동화를 앞세워 배송 기간을 줄이고 배송 비용을 낮추는 데 주력하고 있다.</p><p>국내 F익스프레스는 동남아 주요 국가 배송 기간을 평균 5일에서 3일로 단축했다고 밝혔다. 회사 관계자는 “현지 거점 창고에 인기 상품을 미리 보관하는 방식으로 속도를 높였다”며 “화장품과 패션 품목을 중심으로 물량이 빠르게 늘고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 상품을 해외 소비자에게 판매하는 역직구 시장이 커지면서 관련 물류 서비스 경쟁이 치열해지고 있다. 물류업체들은 현지 배송망 제휴와 통관 자동화를 앞세워 배송 기간을 줄이고 배송 비용을 낮추는 데 주력하고 있다.', 'https://picsum.photos/seed/ship-logistics-6/800/500', '2026-09-20 15:11:00+09'::timestamptz, false),
  ('logistics', '[테스트] 창고 로봇 자동화 투자 확대…중견 물류사도 도입 본격화', '<p>대형 물류기업 위주였던 창고 자동화 투자가 중견 물류사로 빠르게 확산되고 있다. 로봇을 구매하지 않고 빌려 쓰는 임대형 서비스가 등장하면서 초기 투자 부담이 크게 줄어든 것이 확산의 주요 배경으로 꼽힌다.</p><p>중견 G물류는 자율이동로봇(AMR) 40대를 도입해 피킹 생산성을 기존 대비 2배 가까이 끌어올렸다고 밝혔다. 회사 관계자는 “구독형 계약으로 도입해 비용 부담이 적었다”며 “인력은 검수와 품질 관리 등 고부가 업무에 재배치했다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '대형 물류기업 위주였던 창고 자동화 투자가 중견 물류사로 빠르게 확산되고 있다. 로봇을 구매하지 않고 빌려 쓰는 임대형 서비스가 등장하면서 초기 투자 부담이 크게 줄어든 것이 확산의 주요 배경으로 꼽힌다.', 'https://picsum.photos/seed/ship-logistics-7/800/500', '2026-09-18 17:54:00+09'::timestamptz, false),
  ('logistics', '[테스트] “물류는 데이터 산업”…H물류 대표가 밝힌 디지털 전환 로드맵', '<p>H물류 대표는 최근 기자 간담회에서 향후 3년간 물류 데이터 플랫폼 구축에 집중 투자하겠다고 밝혔다. 창고와 운송, 통관 정보를 하나의 시스템으로 묶어 고객사에 화물 흐름 전반의 실시간 가시성을 제공한다는 구상이다.</p><p>그는 “화물이 어디에 있는지 묻는 전화가 사라지는 것이 첫 번째 목표”라고 말했다. 이어 “축적된 데이터를 바탕으로 수요 예측과 재고 최적화 서비스까지 제공해 단순 운송업체가 아닌 공급망 파트너로 자리매김하겠다”고 강조했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'H물류 대표는 최근 기자 간담회에서 향후 3년간 물류 데이터 플랫폼 구축에 집중 투자하겠다고 밝혔다. 창고와 운송, 통관 정보를 하나의 시스템으로 묶어 고객사에 화물 흐름 전반의 실시간 가시성을 제공한다는 구상이다.', null, '2026-09-16 19:37:00+09'::timestamptz, false),
  ('logistics', '[테스트] 철도-도로 복합운송 활성화…장거리 컨테이너 수송 대안 부상', '<p>장거리 내륙 컨테이너 수송에서 철도와 도로를 연계한 복합운송이 새로운 대안으로 떠오르고 있다. 화물차 운전 인력 부족과 탄소 감축 요구가 맞물리면서 대형 화주를 중심으로 철도 수송에 대한 관심이 커지는 분위기다.</p><p>업계에 따르면 내륙 거점 간 철도 수송을 활용하면 동일 구간 도로 운송 대비 탄소 배출을 70% 이상 줄일 수 있다. I로지스 관계자는 “철도 터미널 양 끝단의 셔틀 운송을 표준화해 전체 소요 시간을 줄이는 것이 과제”라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '장거리 내륙 컨테이너 수송에서 철도와 도로를 연계한 복합운송이 새로운 대안으로 떠오르고 있다. 화물차 운전 인력 부족과 탄소 감축 요구가 맞물리면서 대형 화주를 중심으로 철도 수송에 대한 관심이 커지는 분위기다.', 'https://picsum.photos/seed/ship-logistics-9/800/500', '2026-09-14 21:20:00+09'::timestamptz, false),
  ('logistics', '[테스트] 중앙아시아 육상 운송로 주목…J포워딩, 정기 화물열차 상품 출시', '<p>해상 운송의 대안으로 중국과 중앙아시아를 잇는 육상 운송로가 주목받고 있다. J포워딩은 국내 수출 화주를 대상으로 중앙아시아 주요 도시까지 연결하는 정기 화물열차 복합운송 상품을 새로 출시했다고 밝혔다.</p><p>이 상품은 국내 항만에서 중국 내륙 철도 거점까지 해상으로 운송한 뒤 열차로 환적하는 방식이다. J포워딩 관계자는 “해상 우회 운송보다 운송 기간을 일주일 이상 줄일 수 있다”며 “자동차 부품과 가전 화주들의 문의가 이어지고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '해상 운송의 대안으로 중국과 중앙아시아를 잇는 육상 운송로가 주목받고 있다. J포워딩은 국내 수출 화주를 대상으로 중앙아시아 주요 도시까지 연결하는 정기 화물열차 복합운송 상품을 새로 출시했다고 밝혔다.', 'https://picsum.photos/seed/ship-logistics-10/800/500', '2026-09-12 23:03:00+09'::timestamptz, false),
  ('logistics', '[테스트] 도심 배송 전기화물차 전환 속도…충전 인프라는 과제', '<p>도심 라스트마일 배송에 전기화물차를 투입하는 물류업체가 빠르게 늘고 있다. 국내 K택배는 올해 말까지 도심 배송 차량의 20%를 전기차로 교체하고 2030년까지 이 비율을 절반 이상으로 끌어올린다는 목표를 세웠다.</p><p>다만 물류센터와 배송 거점의 충전 인프라가 부족해 운영 효율이 떨어진다는 지적도 나온다. K택배 관계자는 “차량 교체보다 충전 시설 확보가 더 어려운 상황”이라며 “거점별 급속 충전기 설치를 단계적으로 확대하고 있다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '도심 라스트마일 배송에 전기화물차를 투입하는 물류업체가 빠르게 늘고 있다. 국내 K택배는 올해 말까지 도심 배송 차량의 20%를 전기차로 교체하고 2030년까지 이 비율을 절반 이상으로 끌어올린다는 목표를 세웠다.', 'https://picsum.photos/seed/ship-logistics-11/800/500', '2026-09-11 01:46:00+09'::timestamptz, false),
  ('logistics', '[테스트] 디지털 포워딩 플랫폼 성장…중소 화주 온라인 견적 이용 급증', '<p>온라인으로 운임 견적과 예약을 한 번에 처리하는 디지털 포워딩 플랫폼 이용이 급증하고 있다. 국내 L플랫폼은 올해 신규 가입 화주 수가 전년 대비 두 배 이상 늘었으며 월간 견적 요청 건수도 꾸준히 증가하고 있다고 밝혔다.</p><p>이용자의 상당수는 전담 물류 인력이 없는 중소 수출기업인 것으로 나타났다. L플랫폼 관계자는 “견적 비교부터 서류 작성, 화물 추적까지 한 화면에서 처리할 수 있어 업무 부담이 크게 줄었다는 반응”이라며 “해외 파트너 네트워크를 확대할 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '온라인으로 운임 견적과 예약을 한 번에 처리하는 디지털 포워딩 플랫폼 이용이 급증하고 있다. 국내 L플랫폼은 올해 신규 가입 화주 수가 전년 대비 두 배 이상 늘었으며 월간 견적 요청 건수도 꾸준히 증가하고 있다고 밝혔다.', 'https://picsum.photos/seed/ship-logistics-12/800/500', '2026-09-09 03:29:00+09'::timestamptz, false),
  ('logistics', '[테스트] 반품 물류 전문 서비스 부상…재판매·검수 연계로 부가가치', '<p>이커머스 반품 물량이 늘면서 반품을 전문으로 처리하는 리버스 물류 서비스가 새로운 시장으로 부상하고 있다. 단순 회수를 넘어 검수와 재포장, 재판매까지 하나로 연계하는 방식이 확산되면서 관련 업체들의 투자도 늘고 있다.</p><p>국내 M물류는 반품 전용 센터를 열고 상품 상태에 따라 재입고와 리퍼 판매, 재활용으로 자동 분류하는 체계를 구축했다. 회사 관계자는 “반품 처리 기간을 절반으로 줄여 판매자 재고 손실을 최소화하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '이커머스 반품 물량이 늘면서 반품을 전문으로 처리하는 리버스 물류 서비스가 새로운 시장으로 부상하고 있다. 단순 회수를 넘어 검수와 재포장, 재판매까지 하나로 연계하는 방식이 확산되면서 관련 업체들의 투자도 늘고 있다.', null, '2026-09-07 05:12:00+09'::timestamptz, false),
  ('logistics', '[테스트] 보세창고 수요 증가…글로벌 셀러 재고 거점으로 활용 확대', '<p>해외 판매자들이 국내 보세창고를 동북아 재고 거점으로 활용하는 사례가 늘고 있다. 관세 납부를 유보한 상태로 상품을 보관할 수 있어 주변 여러 국가로 재수출하기에 유리하다는 점이 가장 큰 장점으로 꼽힌다.</p><p>업계에 따르면 수도권과 항만 배후단지 보세창고의 가동률은 최근 90% 안팎까지 높아졌다. N로지스 관계자는 “통관 대행과 재포장 서비스를 함께 제공하면서 글로벌 셀러 유치가 늘었다”며 “추가 보세구역 확보를 추진하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '해외 판매자들이 국내 보세창고를 동북아 재고 거점으로 활용하는 사례가 늘고 있다. 관세 납부를 유보한 상태로 상품을 보관할 수 있어 주변 여러 국가로 재수출하기에 유리하다는 점이 가장 큰 장점으로 꼽힌다.', 'https://picsum.photos/seed/ship-logistics-14/800/500', '2026-09-05 07:55:00+09'::timestamptz, false),
  ('logistics', '[테스트] 신선식품 새벽배송 지방 확대…지역 거점 저온센터 잇따라 개장', '<p>수도권 중심이던 신선식품 새벽배송 서비스가 지방 광역시로 확대되고 있다. 물류업체들은 지역별 저온 거점센터를 잇따라 열며 배송 권역 확장에 속도를 내고 있으며, 지역 소비자들의 이용도 빠르게 늘어나는 추세다.</p><p>국내 O프레시는 영남권과 충청권에 저온 물류센터를 각각 개장하고 해당 지역 새벽배송을 시작했다. 회사 관계자는 “지역 산지와 가까운 거점을 활용해 신선도를 높이고 운송 거리를 줄였다”며 “내년에는 호남권까지 서비스를 넓힐 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수도권 중심이던 신선식품 새벽배송 서비스가 지방 광역시로 확대되고 있다. 물류업체들은 지역별 저온 거점센터를 잇따라 열며 배송 권역 확장에 속도를 내고 있으며, 지역 소비자들의 이용도 빠르게 늘어나는 추세다.', 'https://picsum.photos/seed/ship-logistics-15/800/500', '2026-09-03 09:38:00+09'::timestamptz, false),
  ('logistics', '[테스트] 물류 스타트업 투자 유치 활발…창고관리 SaaS 분야 주목', '<p>투자 시장 위축 속에서도 물류 기술 스타트업의 투자 유치가 이어지고 있다. 특히 중소 물류센터를 겨냥한 클라우드 기반 창고관리시스템(WMS) 분야가 성장 잠재력을 인정받으며 투자자들의 주목을 받고 있다.</p><p>창고관리 소프트웨어 스타트업 P테크는 최근 시리즈B 투자로 150억원을 유치했다고 밝혔다. P테크 대표는 “설치형 시스템을 쓰기 어려운 중소 센터가 월 구독 방식으로 손쉽게 도입할 수 있다는 점이 강점”이라며 “해외 시장 진출도 준비하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '투자 시장 위축 속에서도 물류 기술 스타트업의 투자 유치가 이어지고 있다. 특히 중소 물류센터를 겨냥한 클라우드 기반 창고관리시스템(WMS) 분야가 성장 잠재력을 인정받으며 투자자들의 주목을 받고 있다.', 'https://picsum.photos/seed/ship-logistics-16/800/500', '2026-09-01 11:21:00+09'::timestamptz, false),
  ('logistics', '[테스트] 해상-항공 복합운송 수요 증가…중동 경유 상품 인기', '<p>운임과 운송 기간의 균형을 찾는 화주들이 늘면서 해상과 항공을 결합한 복합운송(Sea&Air) 수요가 증가하고 있다. 아시아에서 해상으로 중동 허브까지 운송한 뒤 항공으로 유럽에 보내는 상품이 특히 인기를 끌고 있다.</p><p>업계에 따르면 이 방식은 항공 직송 대비 비용을 40% 안팎 줄이면서도 해상 운송보다 2주가량 빠르다. Q포워딩 관계자는 “패션과 전자부품처럼 시즌성이 강한 화물의 문의가 많다”며 “환적 구간의 화물 추적 정확도를 높이는 데 공을 들이고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '운임과 운송 기간의 균형을 찾는 화주들이 늘면서 해상과 항공을 결합한 복합운송(Sea&Air) 수요가 증가하고 있다. 아시아에서 해상으로 중동 허브까지 운송한 뒤 항공으로 유럽에 보내는 상품이 특히 인기를 끌고 있다.', 'https://picsum.photos/seed/ship-logistics-17/800/500', '2026-08-30 13:04:00+09'::timestamptz, false),
  ('logistics', '[테스트] 화물차 운임 산정 투명화 움직임…표준 운임표 도입 논의', '<p>화주와 운송사 간 분쟁을 줄이기 위해 화물차 운임 산정 방식을 투명하게 하려는 논의가 업계에서 이어지고 있다. 거리와 차종, 대기 시간 등을 반영한 표준 운임표를 자율적으로 도입하자는 목소리가 커지고 있다.</p><p>R운송협회는 최근 회원사를 대상으로 표준 운임 산정 가이드라인 초안을 공유했다. 협회 관계자는 “상하차 대기 시간에 대한 보상 기준이 명확하지 않아 갈등이 반복돼 왔다”며 “화주 단체와도 협의해 현장 수용성을 높이겠다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '화주와 운송사 간 분쟁을 줄이기 위해 화물차 운임 산정 방식을 투명하게 하려는 논의가 업계에서 이어지고 있다. 거리와 차종, 대기 시간 등을 반영한 표준 운임표를 자율적으로 도입하자는 목소리가 커지고 있다.', null, '2026-08-28 15:47:00+09'::timestamptz, false),
  ('logistics', '[테스트] 물류 전문인력 확보 경쟁…기업 자체 아카데미 운영 늘어', '<p>물류 현장의 디지털 전환이 빨라지면서 데이터와 자동화 설비를 다룰 수 있는 전문인력 확보 경쟁이 치열해지고 있다. 일부 물류기업은 외부 채용만으로는 한계가 있다고 보고 자체 교육 아카데미를 열어 인재를 직접 양성하고 있다.</p><p>국내 S물류는 대학과 협력해 창고 자동화 운영과 물류 데이터 분석 과정을 개설했다고 밝혔다. 회사 관계자는 “현장 경험과 IT 역량을 함께 갖춘 인재가 절대적으로 부족하다”며 “수료생에게는 채용 우대 혜택을 제공할 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '물류 현장의 디지털 전환이 빨라지면서 데이터와 자동화 설비를 다룰 수 있는 전문인력 확보 경쟁이 치열해지고 있다. 일부 물류기업은 외부 채용만으로는 한계가 있다고 보고 자체 교육 아카데미를 열어 인재를 직접 양성하고 있다.', 'https://picsum.photos/seed/ship-logistics-19/800/500', '2026-08-26 17:30:00+09'::timestamptz, false),
  ('port', '[테스트] 부산항 신항 3분기 컨테이너 물동량 분기 기준 최대치 경신', '<p>부산항 신항의 3분기 컨테이너 처리량이 분기 기준 사상 최대치를 기록한 것으로 나타났다. 업계에 따르면 7~9월 신항 터미널들이 처리한 물동량은 약 612만TEU로 전년 동기 대비 6.8% 늘었다.</p><p>북미와 동남아 항로의 수출입 화물이 고르게 증가한 가운데 환적화물이 전체 증가분의 절반 이상을 차지했다. 한 터미널운영사 관계자는 “선사들의 기항 재편으로 신항 선석 활용률이 크게 높아졌다”며 “4분기에도 증가세가 이어질 것”이라고 내다봤다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '부산항 신항의 3분기 컨테이너 처리량이 분기 기준 사상 최대치를 기록한 것으로 나타났다. 업계에 따르면 7~9월 신항 터미널들이 처리한 물동량은 약 612만TEU로 전년 동기 대비 6.8% 늘었다.', 'https://picsum.photos/seed/ship-port-0/800/500', '2026-10-01 22:46:00+09'::timestamptz, true),
  ('port', '[테스트] 광양항 완전자동화 컨테이너 부두 시범 운영 돌입', '<p>광양항에서 국내 기술로 구축한 완전자동화 컨테이너 부두가 이달부터 시범 운영에 들어갔다. 원격 안벽크레인과 무인 이송장비, 자동화 야드크레인이 하나의 운영체계로 연동되는 방식으로, 국내 항만 자동화 전환의 시험대가 될 것으로 주목받고 있다.</p><p>시범 운영 기간에는 하루 평균 선박 2척 규모의 하역 작업을 자동화 설비로 처리하며 생산성과 안전성을 점검한다. A항만운영사 관계자는 “장비 간 데이터 연동 안정성을 충분히 검증한 뒤 상업 운영 전환 시점을 확정할 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '광양항에서 국내 기술로 구축한 완전자동화 컨테이너 부두가 이달부터 시범 운영에 들어갔다. 원격 안벽크레인과 무인 이송장비, 자동화 야드크레인이 하나의 운영체계로 연동되는 방식으로, 국내 항만 자동화 전환의 시험대가 될 것으로 주목받고 있다.', 'https://picsum.photos/seed/ship-port-1/800/500', '2026-09-30 00:29:00+09'::timestamptz, false),
  ('port', '[테스트] 인천항 배후단지에 전자상거래 전용 물류센터 착공', '<p>인천항 배후단지에 해외직구와 역직구 화물을 전문으로 처리하는 대형 물류센터가 착공했다. 연면적 약 8만5천㎡ 규모의 이 센터는 2028년 상반기 준공을 목표로 하며, 수도권 해상 특송 화물의 핵심 처리 거점 역할을 맡게 된다.</p><p>센터에는 자동 분류 설비와 통관 연계 시스템이 갖춰져 입항부터 출고까지 걸리는 시간을 크게 줄일 수 있을 것으로 기대된다. 사업을 맡은 B물류개발사 측은 “해상 특송 수요가 꾸준히 늘고 있어 항만 인접 입지의 경쟁력이 높다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '인천항 배후단지에 해외직구와 역직구 화물을 전문으로 처리하는 대형 물류센터가 착공했다. 연면적 약 8만5천㎡ 규모의 이 센터는 2028년 상반기 준공을 목표로 하며, 수도권 해상 특송 화물의 핵심 처리 거점 역할을 맡게 된다.', null, '2026-09-28 02:12:00+09'::timestamptz, false),
  ('port', '[테스트] 평택항 한중 카페리 화물 회복세 뚜렷', '<p>평택항을 오가는 한중 카페리의 화물 처리량이 뚜렷한 회복세를 보이며 노선 운영에도 활기가 돌고 있다. 업계에 따르면 올해 1~8월 평택항 카페리 화물은 약 31만TEU로 지난해 같은 기간보다 9.2% 증가해 최근 몇 년 사이 가장 높은 증가율을 기록했다.</p><p>중국 산둥성과 장쑤성 지역의 중간재 교역이 살아나면서 정기 화물 수요가 늘어난 것이 주된 요인으로 꼽힌다. 한 카페리 선사 관계자는 “빠른 운송 시간을 선호하는 화주가 늘고 있어 주간 운항 횟수 확대를 검토하고 있다”고 전했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '평택항을 오가는 한중 카페리의 화물 처리량이 뚜렷한 회복세를 보이며 노선 운영에도 활기가 돌고 있다. 업계에 따르면 올해 1~8월 평택항 카페리 화물은 약 31만TEU로 지난해 같은 기간보다 9.2% 증가해 최근 몇 년 사이 가장 높은 증가율을 기록했다.', 'https://picsum.photos/seed/ship-port-3/800/500', '2026-09-26 04:55:00+09'::timestamptz, false),
  ('port', '[테스트] 동북아 환적 허브 경쟁 가열, 국내 항만 인센티브 강화', '<p>동북아 주요 항만 간 환적화물 유치 경쟁이 갈수록 치열해지면서 국내 항만들도 인센티브 제도를 손질하고 있다. 신규 항로 개설 선사와 환적 물량 증가 선사에 대한 지원 폭을 넓히는 것이 핵심으로, 업계는 연내 세부 기준이 확정될 것으로 보고 있다.</p><p>업계에서는 싱가포르항과 중국 주요 항만이 대규모 자동화 투자로 처리 능력을 키우는 만큼 비용과 서비스 경쟁력을 함께 높여야 한다는 목소리가 나온다. 한 항만 관계자는 “선석 생산성과 연결성이 결국 선사의 선택을 좌우한다”고 강조했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '동북아 주요 항만 간 환적화물 유치 경쟁이 갈수록 치열해지면서 국내 항만들도 인센티브 제도를 손질하고 있다. 신규 항로 개설 선사와 환적 물량 증가 선사에 대한 지원 폭을 넓히는 것이 핵심으로, 업계는 연내 세부 기준이 확정될 것으로 보고 있다.', 'https://picsum.photos/seed/ship-port-4/800/500', '2026-09-24 06:38:00+09'::timestamptz, false),
  ('port', '[테스트] 디지털 트윈 기반 스마트 항만 운영 플랫폼 본격 가동', '<p>항만 전체를 가상 공간에 그대로 구현한 디지털 트윈 운영 플랫폼이 국내 컨테이너 터미널에서 본격 가동됐다. 선박 입항 일정부터 야드 장치율, 게이트 혼잡도까지 실시간으로 시뮬레이션할 수 있어 터미널 운영 방식에 큰 변화가 예상된다.</p><p>플랫폼을 도입한 C터미널은 시범 기간 동안 트럭 평균 대기시간을 약 23% 줄였다고 밝혔다. C터미널 관계자는 “선석 배정과 장비 배치를 사전에 최적화할 수 있게 되면서 운영 효율이 눈에 띄게 개선됐다”며 “인공지능 예측 기능도 단계적으로 추가할 예정”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '항만 전체를 가상 공간에 그대로 구현한 디지털 트윈 운영 플랫폼이 국내 컨테이너 터미널에서 본격 가동됐다. 선박 입항 일정부터 야드 장치율, 게이트 혼잡도까지 실시간으로 시뮬레이션할 수 있어 터미널 운영 방식에 큰 변화가 예상된다.', 'https://picsum.photos/seed/ship-port-5/800/500', '2026-09-22 08:21:00+09'::timestamptz, true),
  ('port', '[테스트] 컨테이너 부두 육상전원공급장치 설치 확대 속도', '<p>정박 중인 선박에 육상 전력을 공급하는 육상전원공급장치 설치가 국내 주요 컨테이너 부두에서 빠르게 확대되고 있다. 선박이 정박 중 보조엔진을 끄고 육상 전력을 쓸 수 있어 항만 인근 대기오염과 탄소 배출을 동시에 줄이는 효과가 크다는 평가다.</p><p>업계에 따르면 올해 말까지 주요 항만 컨테이너 선석의 절반가량에 관련 설비가 갖춰질 전망이다. 한 선사 관계자는 “유럽 등 해외 항만에서도 육상전원 사용 요구가 커지고 있어 선박 측 수전 설비 개조도 함께 진행하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '정박 중인 선박에 육상 전력을 공급하는 육상전원공급장치 설치가 국내 주요 컨테이너 부두에서 빠르게 확대되고 있다. 선박이 정박 중 보조엔진을 끄고 육상 전력을 쓸 수 있어 항만 인근 대기오염과 탄소 배출을 동시에 줄이는 효과가 크다는 평가다.', 'https://picsum.photos/seed/ship-port-6/800/500', '2026-09-20 10:04:00+09'::timestamptz, false),
  ('port', '[테스트] 로테르담항과 국내 항만 간 친환경 해운회랑 협력 논의', '<p>유럽 최대 항만인 로테르담항과 국내 항만을 잇는 친환경 해운회랑 구축 논의가 본격화하고 있다. 저탄소 연료 공급망 구축과 선박 배출 데이터 공유 체계를 마련하는 것이 주요 의제로, 참여 기관들은 내년 중 공동 이행계획을 내놓는 것을 목표로 하고 있다.</p><p>참여 기관들은 메탄올과 암모니아 등 대체연료 벙커링 기반을 단계적으로 갖추는 방안을 검토하고 있다. 협의에 참여한 한 관계자는 “항로 양 끝단의 항만이 같은 기준으로 연료와 인프라를 준비해야 선사들이 친환경 선박 투입을 결정할 수 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '유럽 최대 항만인 로테르담항과 국내 항만을 잇는 친환경 해운회랑 구축 논의가 본격화하고 있다. 저탄소 연료 공급망 구축과 선박 배출 데이터 공유 체계를 마련하는 것이 주요 의제로, 참여 기관들은 내년 중 공동 이행계획을 내놓는 것을 목표로 하고 있다.', null, '2026-09-18 12:47:00+09'::timestamptz, false),
  ('port', '[테스트] D터미널운영사, 야드 하역장비 전동화에 대규모 투자', '<p>D터미널운영사가 부산항 터미널의 야드 하역장비를 전기 구동 방식으로 전환하는 데 대규모 투자를 단행한다. 향후 3년간 디젤 야드트랙터와 야드크레인 대부분을 전동화 장비로 교체한다는 계획으로, 국내 단일 터미널 기준 최대 규모의 친환경 장비 투자다.</p><p>회사 측은 장비 전환이 마무리되면 연간 연료비와 탄소 배출량을 각각 30% 이상 줄일 수 있을 것으로 보고 있다. D터미널운영사 관계자는 “충전 인프라와 운영 소프트웨어를 함께 구축해 작업 중단 없이 단계적으로 교체할 것”이라고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'D터미널운영사가 부산항 터미널의 야드 하역장비를 전기 구동 방식으로 전환하는 데 대규모 투자를 단행한다. 향후 3년간 디젤 야드트랙터와 야드크레인 대부분을 전동화 장비로 교체한다는 계획으로, 국내 단일 터미널 기준 최대 규모의 친환경 장비 투자다.', 'https://picsum.photos/seed/ship-port-8/800/500', '2026-09-16 14:30:00+09'::timestamptz, false),
  ('port', '[테스트] 부산항 환적화물 비중 상승, 글로벌 선사 기항 늘어', '<p>부산항 전체 컨테이너 물동량에서 환적화물이 차지하는 비중이 꾸준히 높아지고 있다. 업계에 따르면 올해 상반기 부산항 환적 비중은 약 55%로 지난해보다 2%포인트가량 상승하며 동북아 환적 거점으로서의 입지를 다시 한번 확인했다.</p><p>글로벌 선사들이 아시아 역내 네트워크를 재편하면서 부산항을 중간 거점으로 활용하는 사례가 늘어난 영향으로 풀이된다. 한 해운업계 관계자는 “연결 항로가 많고 환적 처리 시간이 짧다는 점이 강점으로 작용하고 있다”고 평가했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '부산항 전체 컨테이너 물동량에서 환적화물이 차지하는 비중이 꾸준히 높아지고 있다. 업계에 따르면 올해 상반기 부산항 환적 비중은 약 55%로 지난해보다 2%포인트가량 상승하며 동북아 환적 거점으로서의 입지를 다시 한번 확인했다.', 'https://picsum.photos/seed/ship-port-9/800/500', '2026-09-14 16:13:00+09'::timestamptz, false),
  ('port', '[테스트] 항만 배후단지 냉동·냉장 창고 수요 급증', '<p>수입 식품과 신선 농수산물 물동량이 늘면서 항만 배후단지 내 냉동·냉장 창고 수요가 빠르게 증가하고 있다. 주요 항만 배후단지의 저온 창고 공실률은 한 자릿수 초반까지 떨어진 것으로 알려졌으며, 신규 공급이 수요를 따라가지 못하는 상황이다.</p><p>이에 따라 물류업체들은 자동화 설비를 갖춘 다층형 저온 물류센터 개발 계획을 잇따라 내놓으며 시장 선점에 나서고 있다. E물류 관계자는 “항만에서 바로 반입해 보관과 분류까지 처리할 수 있는 입지에 대한 화주 문의가 크게 늘었다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수입 식품과 신선 농수산물 물동량이 늘면서 항만 배후단지 내 냉동·냉장 창고 수요가 빠르게 증가하고 있다. 주요 항만 배후단지의 저온 창고 공실률은 한 자릿수 초반까지 떨어진 것으로 알려졌으며, 신규 공급이 수요를 따라가지 못하는 상황이다.', 'https://picsum.photos/seed/ship-port-10/800/500', '2026-09-12 18:56:00+09'::timestamptz, false),
  ('port', '[테스트] 컨테이너 반출입 예약제에 블록체인 기술 접목', '<p>컨테이너 터미널의 반출입 예약 시스템에 블록체인 기술을 접목한 실증 사업이 진행되고 있다. 선사와 운송사, 터미널이 화물 반출 정보를 위변조 없이 실시간으로 공유해 서류 확인 절차를 줄이고 게이트 혼잡을 완화하는 것이 목표다.</p><p>실증에 참여한 운송업체들은 서류 확인 절차가 줄어 게이트 통과 시간이 단축됐다고 평가했다. 사업을 주관한 F정보기술사 관계자는 “참여 기관을 늘려 내년에는 주요 터미널 전반으로 확대 적용하는 방안을 협의하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '컨테이너 터미널의 반출입 예약 시스템에 블록체인 기술을 접목한 실증 사업이 진행되고 있다. 선사와 운송사, 터미널이 화물 반출 정보를 위변조 없이 실시간으로 공유해 서류 확인 절차를 줄이고 게이트 혼잡을 완화하는 것이 목표다.', 'https://picsum.photos/seed/ship-port-11/800/500', '2026-09-10 20:39:00+09'::timestamptz, false),
  ('port', '[테스트] 울산항 액체화물 처리량 증가세, 에너지 허브 기능 강화', '<p>울산항의 액체화물 처리량이 증가세를 이어가며 동북아 에너지 물류 거점으로서의 위상이 높아지고 있다. 업계에 따르면 올해 1~8월 울산항의 액체화물 처리량은 전년 동기 대비 4.1% 늘어나며 8개월 연속 증가세를 기록했다.</p><p>석유제품과 화학제품 수출이 견조한 가운데 탱크터미널 신규 설비가 가동에 들어간 점도 처리량 확대에 힘을 보탰다. 한 탱크터미널 운영사 관계자는 “향후 수소와 암모니아 등 친환경 에너지 화물 저장 수요에도 대비하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '울산항의 액체화물 처리량이 증가세를 이어가며 동북아 에너지 물류 거점으로서의 위상이 높아지고 있다. 업계에 따르면 올해 1~8월 울산항의 액체화물 처리량은 전년 동기 대비 4.1% 늘어나며 8개월 연속 증가세를 기록했다.', null, '2026-09-08 22:22:00+09'::timestamptz, false),
  ('port', '[테스트] 항만 내 자율주행 컨테이너 트럭 실증 2단계 착수', '<p>컨테이너 터미널 내부에서 자율주행 트럭으로 화물을 옮기는 실증 사업이 2단계에 들어갔다. 1단계에서 지정 구간 주행 안정성을 검증한 데 이어 이번에는 안벽크레인, 야드크레인과 연계한 실제 하역 작업 환경에서 운행을 시험한다.</p><p>실증에는 라이다와 고정밀 지도 기반의 자율주행 트럭 여러 대가 투입되며 야간 작업 환경에서의 안정성도 함께 점검한다. G모빌리티 관계자는 “항만은 정해진 경로와 통제된 환경이라 자율주행 상용화가 가장 먼저 이뤄질 수 있는 분야”라고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '컨테이너 터미널 내부에서 자율주행 트럭으로 화물을 옮기는 실증 사업이 2단계에 들어갔다. 1단계에서 지정 구간 주행 안정성을 검증한 데 이어 이번에는 안벽크레인, 야드크레인과 연계한 실제 하역 작업 환경에서 운행을 시험한다.', 'https://picsum.photos/seed/ship-port-13/800/500', '2026-09-07 00:05:00+09'::timestamptz, false),
  ('port', '[테스트] 인천항, 베트남·태국 잇는 신규 컨테이너 항로 개설', '<p>인천항과 베트남, 태국을 연결하는 신규 컨테이너 정기 항로가 이달 첫 운항을 시작했다. 2천TEU급 컨테이너선 3척이 투입돼 인천~호찌민~방콕을 주 1회 일정으로 순환 운항하며, 수도권 화주들의 동남아 수출입 선택지가 한층 넓어졌다.</p><p>수도권 화주들은 그동안 부산항을 거쳐야 했던 동남아 화물을 인천항에서 바로 처리할 수 있게 돼 내륙 운송비를 줄일 수 있을 것으로 기대된다. 항로를 개설한 H선사 측은 “전자제품 부품과 소비재 중심으로 초기 화물을 확보했다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '인천항과 베트남, 태국을 연결하는 신규 컨테이너 정기 항로가 이달 첫 운항을 시작했다. 2천TEU급 컨테이너선 3척이 투입돼 인천~호찌민~방콕을 주 1회 일정으로 순환 운항하며, 수도권 화주들의 동남아 수출입 선택지가 한층 넓어졌다.', 'https://picsum.photos/seed/ship-port-14/800/500', '2026-09-05 02:48:00+09'::timestamptz, false),
  ('port', '[테스트] 스마트 항만 전문인력 양성 과정 첫 수료생 배출', '<p>자동화 항만 운영에 필요한 전문인력을 키우기 위한 교육 과정이 첫 수료생을 배출했다. 참가자들은 원격 크레인 조작과 터미널 운영 시스템 관리, 물류 데이터 분석 등을 6개월간 이론과 현장 실습을 병행하며 집중적으로 교육받았다.</p><p>수료생 상당수는 국내 터미널운영사와 항만 정보기술 기업에 채용될 예정인 것으로 알려졌다. 교육을 담당한 한 관계자는 “현장 경험이 있는 기존 인력의 직무 전환 교육도 병행해 자동화 전환 과정에서 인력 공백이 없도록 할 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '자동화 항만 운영에 필요한 전문인력을 키우기 위한 교육 과정이 첫 수료생을 배출했다. 참가자들은 원격 크레인 조작과 터미널 운영 시스템 관리, 물류 데이터 분석 등을 6개월간 이론과 현장 실습을 병행하며 집중적으로 교육받았다.', 'https://picsum.photos/seed/ship-port-15/800/500', '2026-09-03 04:31:00+09'::timestamptz, false),
  ('port', '[테스트] 서남해안 항만 자동차 수출 물량 늘며 전용부두 확충 검토', '<p>완성차 수출 물량이 증가하면서 목포항과 군산항 등 서남해안 항만의 자동차 처리량도 함께 늘고 있다. 업계에서는 선적 대기 차량이 늘어나는 상황에 대비해 자동차 전용부두와 야적장을 확충해야 한다는 의견이 꾸준히 나오고 있다.</p><p>특히 전기차 수출이 늘면서 차량 보관 구역의 충전 설비와 안전 관리 기준을 강화해야 한다는 요구도 커지고 있다. 한 자동차운반선 대리점 관계자는 “선적 대기 차량이 늘어나는 시기에는 야적 공간 확보가 가장 큰 과제”라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '완성차 수출 물량이 증가하면서 목포항과 군산항 등 서남해안 항만의 자동차 처리량도 함께 늘고 있다. 업계에서는 선적 대기 차량이 늘어나는 상황에 대비해 자동차 전용부두와 야적장을 확충해야 한다는 의견이 꾸준히 나오고 있다.', 'https://picsum.photos/seed/ship-port-16/800/500', '2026-09-01 06:14:00+09'::timestamptz, false),
  ('port', '[테스트] 항만 하역장비에 배출가스 저감장치 장착 확대', '<p>항만 내 미세먼지를 줄이기 위해 노후 하역장비에 배출가스 저감장치를 장착하는 작업이 주요 항만을 중심으로 확대되고 있다. 리치스태커와 대형 지게차, 야드트랙터 등 전동화 전환이 아직 이뤄지지 않은 디젤 장비가 주요 대상이다.</p><p>저감장치를 장착한 장비는 미세먼지 배출량을 80% 이상 줄일 수 있는 것으로 알려졌다. I하역사 관계자는 “전동화 장비로 교체하기 전까지 기존 장비의 배출을 최소화하는 것이 현실적인 대안”이라며 “올해 안에 보유 장비 대부분에 장착을 마칠 계획”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '항만 내 미세먼지를 줄이기 위해 노후 하역장비에 배출가스 저감장치를 장착하는 작업이 주요 항만을 중심으로 확대되고 있다. 리치스태커와 대형 지게차, 야드트랙터 등 전동화 전환이 아직 이뤄지지 않은 디젤 장비가 주요 대상이다.', null, '2026-08-30 08:57:00+09'::timestamptz, false),
  ('port', '[테스트] 북극항로 상용화 대비 항만 물류 연구 활발', '<p>북극항로 활용 가능성이 높아지면서 국내 항만을 북극항로 거점으로 활용하기 위한 연구가 활발하게 진행되고 있다. 기존 수에즈 항로 대비 운항 거리를 크게 줄일 수 있다는 점이 주목받으면서 관련 연구 과제도 늘고 있다.</p><p>연구진은 내빙 선박 운영 비용과 계절별 운항 가능 기간, 거점 항만의 연료 공급 여건 등을 종합적으로 분석하고 있다. 한 해운 연구기관 관계자는 “당장 대규모 상용화는 어렵지만 중장기적으로 항만 기능을 미리 준비해 둘 필요가 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '북극항로 활용 가능성이 높아지면서 국내 항만을 북극항로 거점으로 활용하기 위한 연구가 활발하게 진행되고 있다. 기존 수에즈 항로 대비 운항 거리를 크게 줄일 수 있다는 점이 주목받으면서 관련 연구 과제도 늘고 있다.', 'https://picsum.photos/seed/ship-port-18/800/500', '2026-08-28 10:40:00+09'::timestamptz, false),
  ('port', '[테스트] 원격조종 안벽크레인 확산, 작업 환경 개선 효과', '<p>관제실에서 안벽크레인을 원격으로 조종하는 방식이 국내 컨테이너 터미널에 빠르게 확산되고 있다. 수십m 높이의 운전석 대신 지상 관제실에서 여러 대의 크레인 영상을 보며 작업하는 방식으로, 작업자 한 명이 복수의 장비를 관리할 수 있다.</p><p>원격조종 도입 이후 작업자들의 피로도가 줄고 근무 환경이 개선됐다는 평가가 나온다. J터미널 관계자는 “초기에는 숙련도 확보에 시간이 걸렸지만 현재는 기존 방식과 비슷한 생산성을 유지하고 있다”며 “추가 장비에도 원격 시스템을 적용할 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '관제실에서 안벽크레인을 원격으로 조종하는 방식이 국내 컨테이너 터미널에 빠르게 확산되고 있다. 수십m 높이의 운전석 대신 지상 관제실에서 여러 대의 크레인 영상을 보며 작업하는 방식으로, 작업자 한 명이 복수의 장비를 관리할 수 있다.', 'https://picsum.photos/seed/ship-port-19/800/500', '2026-08-26 12:23:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 국내 A항공사 3분기 화물 매출 두 자릿수 증가', '<p>국내 A항공사의 3분기 화물사업 매출이 전년 동기 대비 두 자릿수 증가율을 기록한 것으로 나타났다. 업계에 따르면 반도체와 전자상거래 화물 수요가 동시에 늘면서 화물 수송량이 약 12% 늘어난 것으로 집계됐다.</p><p>미주와 유럽 노선의 화물기 탑재율이 높은 수준을 유지한 것도 실적 개선에 힘을 보탰다. A항공사 관계자는 “고부가가치 화물 비중을 꾸준히 높여온 전략이 성과로 이어지고 있다”며 “연말 성수기에 대비해 임시 화물편 투입도 검토하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 A항공사의 3분기 화물사업 매출이 전년 동기 대비 두 자릿수 증가율을 기록한 것으로 나타났다. 업계에 따르면 반도체와 전자상거래 화물 수요가 동시에 늘면서 화물 수송량이 약 12% 늘어난 것으로 집계됐다.', 'https://picsum.photos/seed/ship-air-cargo-0/800/500', '2026-10-01 17:39:00+09'::timestamptz, true),
  ('air-cargo', '[테스트] 인천공항 화물터미널 증축 착공, 연간 처리능력 확대', '<p>인천공항 화물지역에서 신규 화물터미널 증축 공사가 착공했다. 증축이 완료되면 해당 구역의 연간 화물 처리능력은 약 60만톤가량 늘어날 것으로 예상되며, 전자상거래와 의약품 등 고부가가치 화물 처리 여건도 크게 개선될 전망이다.</p><p>새 터미널에는 자동화 화물 보관 설비와 온도 관리 구역, 특송 전용 처리 공간이 들어선다. 공항 화물업계 관계자는 “전자상거래와 의약품 화물이 빠르게 늘면서 처리 공간 부족 문제가 꾸준히 제기돼 왔다”며 “동북아 화물 허브 경쟁력 강화에 도움이 될 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '인천공항 화물지역에서 신규 화물터미널 증축 공사가 착공했다. 증축이 완료되면 해당 구역의 연간 화물 처리능력은 약 60만톤가량 늘어날 것으로 예상되며, 전자상거래와 의약품 등 고부가가치 화물 처리 여건도 크게 개선될 전망이다.', null, '2026-09-29 19:22:00+09'::timestamptz, true),
  ('air-cargo', '[테스트] 해외 전자상거래 특송 물량 증가, 공항 통관 처리 분주', '<p>해외 온라인 쇼핑 수요가 꾸준히 늘면서 공항 특송 화물 처리 물량도 빠르게 증가하고 있다. 업계에 따르면 올해 1~8월 국내 공항을 통해 들어온 항공 특송 화물 건수는 전년 동기 대비 약 18% 늘어나 연간 최대 기록 경신이 유력하다.</p><p>특송업체들은 야간 통관 인력을 늘리고 자동 분류기를 추가 설치하는 등 처리 능력 확대에 나섰다. B특송사 관계자는 “소형 화물 비중이 커지면서 건당 처리 속도가 경쟁력의 핵심이 됐다”며 “인공지능 기반 화물 분류 시스템 도입도 준비하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '해외 온라인 쇼핑 수요가 꾸준히 늘면서 공항 특송 화물 처리 물량도 빠르게 증가하고 있다. 업계에 따르면 올해 1~8월 국내 공항을 통해 들어온 항공 특송 화물 건수는 전년 동기 대비 약 18% 늘어나 연간 최대 기록 경신이 유력하다.', 'https://picsum.photos/seed/ship-air-cargo-2/800/500', '2026-09-27 21:05:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 여객기 개조 화물기 도입 늘어, 중형 화물기 시장 활기', '<p>퇴역 여객기를 화물기로 개조해 투입하는 사례가 늘면서 중형 화물기 시장이 활기를 띠고 있다. 신조 화물기보다 도입 비용이 낮고 인도 기간이 짧아 화물 수요 변화에 빠르게 대응할 수 있다는 점이 항공사와 임대사들에게 장점으로 꼽힌다.</p><p>특히 전자상거래 화물처럼 부피는 크지만 무게가 가벼운 화물을 수송하는 데 적합하다는 평가가 나온다. 한 항공기 임대업계 관계자는 “아시아 지역 항공사들의 개조 화물기 문의가 지난해보다 눈에 띄게 늘었다”며 “개조 작업 일정도 빠르게 채워지고 있다”고 전했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '퇴역 여객기를 화물기로 개조해 투입하는 사례가 늘면서 중형 화물기 시장이 활기를 띠고 있다. 신조 화물기보다 도입 비용이 낮고 인도 기간이 짧아 화물 수요 변화에 빠르게 대응할 수 있다는 점이 항공사와 임대사들에게 장점으로 꼽힌다.', 'https://picsum.photos/seed/ship-air-cargo-3/800/500', '2026-09-25 23:48:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 아시아발 항공화물 운임 소폭 하락, 성수기 앞두고 관망세', '<p>아시아발 주요 노선의 항공화물 운임이 최근 몇 주간 소폭 하락세를 보이고 있다. 업계에 따르면 아시아~북미 노선의 평균 항공화물 운임은 한 달 전보다 약 3% 낮은 수준을 나타냈으며, 유럽 노선도 비슷한 흐름을 보였다.</p><p>여름철 비수기 영향과 공급석 증가가 겹친 결과로 풀이되며 시장에서는 연말 성수기를 앞두고 관망하는 분위기가 강하다. 한 포워딩업체 관계자는 “10월 이후 신제품 출시와 쇼핑 시즌 수요가 본격화되면 운임이 다시 오를 가능성이 높다”고 내다봤다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '아시아발 주요 노선의 항공화물 운임이 최근 몇 주간 소폭 하락세를 보이고 있다. 업계에 따르면 아시아~북미 노선의 평균 항공화물 운임은 한 달 전보다 약 3% 낮은 수준을 나타냈으며, 유럽 노선도 비슷한 흐름을 보였다.', 'https://picsum.photos/seed/ship-air-cargo-4/800/500', '2026-09-24 01:31:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 반도체 장비·부품 항공 수송 수요 꾸준히 증가', '<p>반도체 장비와 부품의 항공 수송 수요가 꾸준히 증가하며 항공화물 시장의 버팀목 역할을 하고 있다. 고가이면서 납기가 중요한 품목 특성상 항공 운송 선호도가 높아, 생산설비 증설이 이어지는 시기에는 대형 장비 수송 수요도 함께 늘어난다.</p><p>항공사들은 진동과 충격에 민감한 반도체 장비를 안전하게 수송하기 위한 전용 취급 절차를 강화하고 있다. C항공사 화물 담당자는 “정밀 장비 수송 경험이 화주 선택의 중요한 기준이 됐다”며 “전담 팀을 꾸려 대형 장비 수송 수요에 대응하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '반도체 장비와 부품의 항공 수송 수요가 꾸준히 증가하며 항공화물 시장의 버팀목 역할을 하고 있다. 고가이면서 납기가 중요한 품목 특성상 항공 운송 선호도가 높아, 생산설비 증설이 이어지는 시기에는 대형 장비 수송 수요도 함께 늘어난다.', 'https://picsum.photos/seed/ship-air-cargo-5/800/500', '2026-09-22 03:14:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 의약품 콜드체인 항공운송 국제 인증 취득 잇따라', '<p>국내 항공사와 공항 화물터미널들이 의약품 콜드체인 운송 관련 국제 인증을 잇따라 취득하고 있다. 바이오의약품과 백신 등 온도에 민감한 화물 수요가 늘면서 국제 기준에 맞는 운송 품질을 갖추는 것이 화주 확보의 필수 조건이 된 데 따른 것이다.</p><p>인증을 받으려면 화물 접수부터 탑재, 하기까지 전 과정에서 정해진 온도를 유지할 수 있는 설비와 절차를 갖춰야 한다. D화물터미널 관계자는 “인증 취득 이후 글로벌 제약사들의 운송 문의가 크게 늘었다”며 “저온 보관 구역 추가 확장을 검토하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 항공사와 공항 화물터미널들이 의약품 콜드체인 운송 관련 국제 인증을 잇따라 취득하고 있다. 바이오의약품과 백신 등 온도에 민감한 화물 수요가 늘면서 국제 기준에 맞는 운송 품질을 갖추는 것이 화주 확보의 필수 조건이 된 데 따른 것이다.', null, '2026-09-20 05:57:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 글로벌 E특송사, 인천 허브 시설 확장 투자', '<p>글로벌 E특송사가 인천공항 내 동북아 허브 시설 확장에 투자한다고 밝혔다. 확장 공사가 완료되면 인천 허브의 시간당 화물 처리 능력은 현재보다 약 40% 늘어나 아시아 역내 특송 네트워크의 핵심 거점 역할이 한층 강화될 전망이다.</p><p>새 시설에는 고속 자동 분류 설비와 대형 화물 전용 처리 라인이 갖춰질 예정이다. E특송사 관계자는 “한국은 중국과 일본, 동남아를 잇는 지리적 이점이 커 아시아 네트워크의 핵심 거점”이라며 “환적 특송 화물 비중을 더 높여 나갈 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '글로벌 E특송사가 인천공항 내 동북아 허브 시설 확장에 투자한다고 밝혔다. 확장 공사가 완료되면 인천 허브의 시간당 화물 처리 능력은 현재보다 약 40% 늘어나 아시아 역내 특송 네트워크의 핵심 거점 역할이 한층 강화될 전망이다.', 'https://picsum.photos/seed/ship-air-cargo-7/800/500', '2026-09-18 07:40:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 저비용항공사들, 여객기 하부 화물칸 활용 확대', '<p>국내 저비용항공사들이 여객기 하부 화물칸을 활용한 화물사업을 확대하고 있다. 일본과 동남아 등 중단거리 국제선을 중심으로 전자상거래 화물과 신선식품 수송을 늘리며 여객 외 수익원을 다변화하려는 추세다.</p><p>일부 항공사는 화물 전담 조직을 신설하고 포워딩업체와 장기 계약을 맺는 등 사업 기반을 다지고 있다. F항공 관계자는 “여객 수익에 더해 화물 수익을 안정적으로 확보하는 것이 중요해졌다”며 “노선별 화물 수요를 분석해 판매 전략을 세우고 있다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 저비용항공사들이 여객기 하부 화물칸을 활용한 화물사업을 확대하고 있다. 일본과 동남아 등 중단거리 국제선을 중심으로 전자상거래 화물과 신선식품 수송을 늘리며 여객 외 수익원을 다변화하려는 추세다.', 'https://picsum.photos/seed/ship-air-cargo-8/800/500', '2026-09-16 09:23:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 항공화물 전자운송장 사용률 꾸준히 상승', '<p>종이 서류 대신 전자 방식으로 화물 정보를 주고받는 항공화물 전자운송장 사용률이 꾸준히 높아지고 있다. 업계에 따르면 국내 출발 국제 항공화물의 전자운송장 사용률은 80%를 넘어선 것으로 추정된다.</p><p>전자운송장을 사용하면 서류 분실 위험이 줄고 화물 처리 시간도 단축할 수 있다. 한 포워딩업계 관계자는 “중소 포워더들도 전자 시스템에 익숙해지면서 사용률이 빠르게 올라가고 있다”며 “통관 서류까지 연계되면 효율이 더 높아질 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '종이 서류 대신 전자 방식으로 화물 정보를 주고받는 항공화물 전자운송장 사용률이 꾸준히 높아지고 있다. 업계에 따르면 국내 출발 국제 항공화물의 전자운송장 사용률은 80%를 넘어선 것으로 추정된다.', 'https://picsum.photos/seed/ship-air-cargo-9/800/500', '2026-09-14 11:06:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 공항 화물터미널에 로봇·인공지능 자동화 설비 도입', '<p>공항 화물터미널에 로봇과 인공지능을 활용한 자동화 설비 도입이 늘고 있다. 화물의 무게와 부피를 자동으로 측정하고 항공기 탑재용 단위적재용기에 실을 최적의 적재 위치를 계산하는 시스템이 대표적이다.</p><p>G화물터미널은 자동화 설비 도입 이후 화물 접수 처리 시간을 약 25% 줄였다고 밝혔다. G화물터미널 관계자는 “반복적인 작업은 설비가 맡고 직원들은 특수 화물 관리 등 숙련이 필요한 업무에 집중할 수 있게 됐다”며 “적용 구역을 단계적으로 넓힐 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '공항 화물터미널에 로봇과 인공지능을 활용한 자동화 설비 도입이 늘고 있다. 화물의 무게와 부피를 자동으로 측정하고 항공기 탑재용 단위적재용기에 실을 최적의 적재 위치를 계산하는 시스템이 대표적이다.', 'https://picsum.photos/seed/ship-air-cargo-10/800/500', '2026-09-12 13:49:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 국산 딸기·포도 항공 수출 증가, 신선화물 수송 경쟁', '<p>국산 딸기와 포도 등 신선 과일의 항공 수출이 증가하면서 항공사들의 신선화물 유치 경쟁이 치열해지고 있다. 동남아와 중동 지역에서 한국산 고급 과일에 대한 수요가 꾸준히 늘면서 올해 신선 과일 항공 수출량은 지난해보다 20% 이상 증가할 것으로 업계는 보고 있다.</p><p>항공사들은 수확 직후 공항까지 신속하게 이동할 수 있도록 산지 연계 물류 서비스를 강화하고 있다. H항공 화물 담당자는 “신선도가 곧 가격으로 이어지는 품목이라 탑재 직전까지 온도 관리가 핵심”이라며 “전용 보냉 컨테이너 투입을 늘리고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국산 딸기와 포도 등 신선 과일의 항공 수출이 증가하면서 항공사들의 신선화물 유치 경쟁이 치열해지고 있다. 동남아와 중동 지역에서 한국산 고급 과일에 대한 수요가 꾸준히 늘면서 올해 신선 과일 항공 수출량은 지난해보다 20% 이상 증가할 것으로 업계는 보고 있다.', null, '2026-09-10 15:32:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 지방공항 국제 화물노선 확대, 청주·대구공항 주목', '<p>청주공항과 대구공항 등 지방공항에서 국제 화물노선을 확대하려는 움직임이 활발하다. 수도권 공항의 혼잡을 피하면서 지역 제조업체와 화주의 내륙 운송비를 줄일 수 있다는 점이 지방공항 화물노선의 강점으로 꼽힌다.</p><p>일부 공항에서는 전자상거래 화물 전용 화물기 정기편 취항이 추진되고 있으며 화물터미널 확충 논의도 이어지고 있다. 한 지역 물류업계 관계자는 “지역 기반 제조업체들의 항공 수출 수요가 꾸준해 노선이 안정적으로 자리 잡을 가능성이 크다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '청주공항과 대구공항 등 지방공항에서 국제 화물노선을 확대하려는 움직임이 활발하다. 수도권 공항의 혼잡을 피하면서 지역 제조업체와 화주의 내륙 운송비를 줄일 수 있다는 점이 지방공항 화물노선의 강점으로 꼽힌다.', 'https://picsum.photos/seed/ship-air-cargo-12/800/500', '2026-09-08 17:15:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 지속가능항공유 활용 화물 운송 프로그램 확산', '<p>항공사들이 지속가능항공유를 활용한 화물 운송 프로그램을 잇따라 내놓고 있다. 화주가 일정 비용을 추가로 부담하면 그만큼 기존 항공유 대신 탄소 배출을 줄인 연료를 사용하고, 감축 실적을 화주의 배출 저감 성과로 인정하는 방식이다.</p><p>글로벌 기업들이 공급망 전반의 탄소 감축 목표를 세우면서 이런 프로그램에 대한 관심이 커지고 있다. I항공사 관계자는 “전자제품과 패션 기업을 중심으로 참여 문의가 늘고 있다”며 “배출 감축량을 증명하는 보고서도 함께 제공하고 있다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '항공사들이 지속가능항공유를 활용한 화물 운송 프로그램을 잇따라 내놓고 있다. 화주가 일정 비용을 추가로 부담하면 그만큼 기존 항공유 대신 탄소 배출을 줄인 연료를 사용하고, 감축 실적을 화주의 배출 저감 성과로 인정하는 방식이다.', 'https://picsum.photos/seed/ship-air-cargo-13/800/500', '2026-09-06 19:58:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 항공화물 보안검색 장비 고도화, 처리 속도 향상', '<p>공항 화물터미널의 보안검색 장비가 고도화되면서 화물 처리 속도도 함께 빨라지고 있다. 대형 팔레트 화물을 분해하지 않고 통째로 검색할 수 있는 고해상도 장비가 도입되면서 검색 정확도와 처리 효율이 동시에 개선되고 있다.</p><p>새 장비는 영상 분석 소프트웨어와 연동돼 검색 요원의 판독을 보조하는 기능도 갖췄다. J화물터미널 관계자는 “검색 정확도는 높이면서 대기 시간은 줄일 수 있게 됐다”며 “특히 성수기 물량이 몰리는 시기에 효과가 클 것으로 기대한다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '공항 화물터미널의 보안검색 장비가 고도화되면서 화물 처리 속도도 함께 빨라지고 있다. 대형 팔레트 화물을 분해하지 않고 통째로 검색할 수 있는 고해상도 장비가 도입되면서 검색 정확도와 처리 효율이 동시에 개선되고 있다.', 'https://picsum.photos/seed/ship-air-cargo-14/800/500', '2026-09-04 21:41:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 한미 노선 항공화물 수요 견조, 화물기 공급 확대', '<p>한국과 미국을 잇는 노선의 항공화물 수요가 견조한 흐름을 이어가고 있다. 항공사들은 늘어난 수요에 대응하기 위해 화물기 운항 횟수를 늘리는 한편 일부 노선에는 대형 화물기를 추가 투입하며 공급을 확대하고 있다.</p><p>전자상거래 화물과 자동차 부품, 배터리 소재 등이 수요를 이끌고 있는 것으로 분석된다. 한 포워딩업체 관계자는 “미국 중서부와 남부 지역 공항으로 향하는 화물이 특히 늘고 있다”며 “직항 화물편이 확대되면 운송 시간이 크게 단축될 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '한국과 미국을 잇는 노선의 항공화물 수요가 견조한 흐름을 이어가고 있다. 항공사들은 늘어난 수요에 대응하기 위해 화물기 운항 횟수를 늘리는 한편 일부 노선에는 대형 화물기를 추가 투입하며 공급을 확대하고 있다.', 'https://picsum.photos/seed/ship-air-cargo-15/800/500', '2026-09-02 23:24:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 국제 전자상거래 반품 물류 서비스 수요 증가', '<p>해외 직구가 일상화되면서 국제 반품을 처리하는 역물류 서비스 수요도 빠르게 늘고 있다. 특송업체와 물류기업들은 반품 화물을 전문으로 처리하는 센터를 잇따라 구축하며 성장하는 역물류 시장 선점에 나서고 있다.</p><p>반품 화물을 국가별로 모아 한꺼번에 항공으로 보내는 통합 운송 방식이 비용 절감 방안으로 주목받고 있다. K물류 관계자는 “소비자 만족도를 높이려는 판매자들이 반품 절차 간소화에 큰 관심을 보이고 있다”며 “통관 연계 서비스도 함께 확대하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '해외 직구가 일상화되면서 국제 반품을 처리하는 역물류 서비스 수요도 빠르게 늘고 있다. 특송업체와 물류기업들은 반품 화물을 전문으로 처리하는 센터를 잇따라 구축하며 성장하는 역물류 시장 선점에 나서고 있다.', null, '2026-09-01 01:07:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 국내 L항공사, 차세대 대형 화물기 신규 도입 계약', '<p>국내 L항공사가 차세대 대형 화물기 도입 계약을 체결했다고 밝혔다. 새로 도입하는 화물기는 기존 기종보다 연료 효율이 약 15% 높고 최대 탑재 용량도 더 커 장거리 화물 노선의 수익성을 높이는 데 기여할 것으로 기대된다.</p><p>L항공사는 신규 화물기를 단계적으로 들여와 노후 기종을 대체하고 장거리 화물 노선 경쟁력을 높일 계획이다. 회사 관계자는 “연료 효율 개선으로 운영비를 줄이는 동시에 탄소 배출 감축 목표 달성에도 기여할 것”이라며 “첫 인도는 수년 내 이뤄질 예정”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 L항공사가 차세대 대형 화물기 도입 계약을 체결했다고 밝혔다. 새로 도입하는 화물기는 기존 기종보다 연료 효율이 약 15% 높고 최대 탑재 용량도 더 커 장거리 화물 노선의 수익성을 높이는 데 기여할 것으로 기대된다.', 'https://picsum.photos/seed/ship-air-cargo-17/800/500', '2026-08-30 03:50:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 항공화물 온라인 예약 플랫폼 이용 급증', '<p>항공화물 공간을 온라인으로 실시간 조회하고 예약하는 디지털 플랫폼 이용이 급증하고 있다. 전화와 이메일로 진행되던 기존 예약 방식이 빠르게 디지털로 전환되면서 화물 예약 시장의 거래 관행도 크게 달라지는 모습이다.</p><p>플랫폼을 이용하면 여러 항공사의 운임과 공간을 한눈에 비교할 수 있어 중소 포워더들의 호응이 크다. M플랫폼 관계자는 “올해 들어 등록 포워더 수가 두 배 가까이 늘었다”며 “화물 추적과 서류 처리 기능까지 통합해 편의성을 높일 것”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '항공화물 공간을 온라인으로 실시간 조회하고 예약하는 디지털 플랫폼 이용이 급증하고 있다. 전화와 이메일로 진행되던 기존 예약 방식이 빠르게 디지털로 전환되면서 화물 예약 시장의 거래 관행도 크게 달라지는 모습이다.', 'https://picsum.photos/seed/ship-air-cargo-18/800/500', '2026-08-28 05:33:00+09'::timestamptz, false),
  ('air-cargo', '[테스트] 해상·항공 복합운송 수요 증가, 인천 연계 물류 주목', '<p>해상과 항공 운송을 결합한 복합운송 수요가 늘면서 인천항과 인천공항을 잇는 연계 물류가 주목받고 있다. 중국 등에서 배로 들어온 화물을 공항으로 옮겨 항공편으로 세계 각지에 보내는 방식으로, 이른바 ‘씨앤에어’ 운송으로 불린다.</p><p>항공 직송보다 비용이 낮고 해상 운송보다 빠르다는 장점 덕분에 전자상거래 화물을 중심으로 이용이 늘고 있다. N포워딩 관계자는 “항만과 공항 간 거리가 가까워 환적 시간이 짧은 점이 큰 경쟁력”이라며 “보세 운송 절차가 더 간소화되면 물량이 늘 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '해상과 항공 운송을 결합한 복합운송 수요가 늘면서 인천항과 인천공항을 잇는 연계 물류가 주목받고 있다. 중국 등에서 배로 들어온 화물을 공항으로 옮겨 항공편으로 세계 각지에 보내는 방식으로, 이른바 ‘씨앤에어’ 운송으로 불린다.', 'https://picsum.photos/seed/ship-air-cargo-19/800/500', '2026-08-26 07:16:00+09'::timestamptz, false),
  ('trade', '[테스트] 동남아향 중소기업 수출 물량 증가…공동물류 수요 확대', '<p>동남아시아 지역으로 향하는 중소기업 수출 물량이 꾸준히 늘면서 소량 화물을 묶어 보내는 공동물류 서비스 수요가 확대되고 있다. 업계에 따르면 올해 3분기 동남아향 소량 혼재(LCL) 화물 처리량은 전년 동기 대비 약 14% 증가한 것으로 집계됐다.</p><p>물류업계는 컨테이너 한 대를 채우기 어려운 중소 화주들이 운임 부담을 줄이기 위해 혼재 서비스를 적극 활용하는 것으로 보고 있다. A물류업체 관계자는 “베트남과 인도네시아 노선을 중심으로 주간 정기 혼재 편을 늘리는 방안을 검토하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '동남아시아 지역으로 향하는 중소기업 수출 물량이 꾸준히 늘면서 소량 화물을 묶어 보내는 공동물류 서비스 수요가 확대되고 있다. 업계에 따르면 올해 3분기 동남아향 소량 혼재(LCL) 화물 처리량은 전년 동기 대비 약 14% 증가한 것으로 집계됐다.', null, '2026-10-01 12:32:00+09'::timestamptz, true),
  ('trade', '[테스트] 원산지 증명 디지털화 확산…수출기업 서류 부담 줄어', '<p>전자 원산지증명서 발급과 교환이 확산되면서 수출기업의 서류 처리 부담이 눈에 띄게 줄어들고 있다. 통관 업계에 따르면 전자 방식으로 원산지 증빙을 처리하는 기업 비중은 최근 1년 사이 절반을 넘어선 것으로 파악됐다.</p><p>업계는 종이 서류를 우편으로 주고받던 과정이 사라지면서 통관 소요 시간이 평균 하루가량 단축됐다고 설명했다. B관세법인 관계자는 “상대국 시스템과의 연계 범위가 넓어질수록 중소기업이 체감하는 효과도 더 커질 것”이라고 전망했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '전자 원산지증명서 발급과 교환이 확산되면서 수출기업의 서류 처리 부담이 눈에 띄게 줄어들고 있다. 통관 업계에 따르면 전자 방식으로 원산지 증빙을 처리하는 기업 비중은 최근 1년 사이 절반을 넘어선 것으로 파악됐다.', 'https://picsum.photos/seed/ship-trade-1/800/500', '2026-09-29 14:15:00+09'::timestamptz, false),
  ('trade', '[테스트] 공급망 재편 속 니어쇼어링 확대…멕시코 물류 거점 주목', '<p>글로벌 공급망 재편이 이어지면서 북미 시장과 가까운 멕시코를 생산·물류 거점으로 활용하려는 움직임이 확대되고 있다. 업계에 따르면 국내 제조기업의 멕시코 현지 창고 임차 문의는 올해 들어 전년보다 20% 이상 늘었다.</p><p>물류업계는 육상 운송과 해상 운송을 결합한 복합운송 상품 개발에 속도를 내고 있다. C포워딩업체 관계자는 “국경 통관 대기 시간을 줄이는 것이 핵심 경쟁력”이라며 “현지 통관 파트너와의 협력 체계를 강화하고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '글로벌 공급망 재편이 이어지면서 북미 시장과 가까운 멕시코를 생산·물류 거점으로 활용하려는 움직임이 확대되고 있다. 업계에 따르면 국내 제조기업의 멕시코 현지 창고 임차 문의는 올해 들어 전년보다 20% 이상 늘었다.', 'https://picsum.photos/seed/ship-trade-2/800/500', '2026-09-27 16:58:00+09'::timestamptz, false),
  ('trade', '[테스트] 수출 중소기업 10곳 중 6곳 “물류비 상승이 최대 애로”', '<p>수출 중소기업 상당수가 여전히 물류비 상승을 가장 큰 경영 애로 요인으로 꼽은 것으로 나타났다. A협회가 회원사 300곳을 대상으로 실시한 설문조사에 따르면 응답 기업의 61%가 물류비 부담을 최우선 해결 과제로 지목했다.</p><p>조사에서는 운임 변동성에 대응하기 위한 장기 운송계약 체결 비율이 20%대에 그친 것으로 나타났다. 협회 관계자는 “중소기업이 개별적으로 선사와 협상하기에는 한계가 있다”며 “공동 구매 방식의 운송계약 모델을 확산할 필요가 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수출 중소기업 상당수가 여전히 물류비 상승을 가장 큰 경영 애로 요인으로 꼽은 것으로 나타났다. A협회가 회원사 300곳을 대상으로 실시한 설문조사에 따르면 응답 기업의 61%가 물류비 부담을 최우선 해결 과제로 지목했다.', 'https://picsum.photos/seed/ship-trade-3/800/500', '2026-09-25 18:41:00+09'::timestamptz, false),
  ('trade', '[테스트] 통관 절차 간소화 논의 본격화…사전 심사 확대 검토', '<p>수출입 화물의 통관 절차를 간소화하기 위한 제도 개선 논의가 본격화하고 있다. 업계에 따르면 화물이 항만에 도착하기 전 서류 심사를 마치는 사전 심사 대상을 확대하는 방안이 주요 논의 과제로 거론되고 있다.</p><p>통관 업계는 사전 심사가 확대되면 항만 내 화물 체류 시간이 줄어 보관료 부담도 함께 낮아질 것으로 기대하고 있다. D관세사무소 대표는 “성실 신고 이력이 있는 기업부터 단계적으로 적용하는 방식이 현실적”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수출입 화물의 통관 절차를 간소화하기 위한 제도 개선 논의가 본격화하고 있다. 업계에 따르면 화물이 항만에 도착하기 전 서류 심사를 마치는 사전 심사 대상을 확대하는 방안이 주요 논의 과제로 거론되고 있다.', 'https://picsum.photos/seed/ship-trade-4/800/500', '2026-09-23 20:24:00+09'::timestamptz, false),
  ('trade', '[테스트] EU 탄소 규제 대응…수출기업 배출량 데이터 관리 강화', '<p>유럽연합의 탄소 관련 규제 강화에 대비해 국내 수출기업들이 제품별 탄소 배출량 데이터 관리 체계를 서둘러 정비하고 있다. 업계에 따르면 철강·알루미늄 등 관련 품목을 수출하는 기업을 중심으로 전문 컨설팅 수요가 크게 늘었다.</p><p>기업들은 원자재 조달부터 운송 단계까지 배출량을 추적할 수 있는 시스템 도입을 검토하고 있다. E무역업체 관계자는 “유럽 바이어가 계약 단계에서부터 배출량 자료를 요구하는 사례가 늘고 있다”며 “데이터 관리가 곧 수출 경쟁력이 됐다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '유럽연합의 탄소 관련 규제 강화에 대비해 국내 수출기업들이 제품별 탄소 배출량 데이터 관리 체계를 서둘러 정비하고 있다. 업계에 따르면 철강·알루미늄 등 관련 품목을 수출하는 기업을 중심으로 전문 컨설팅 수요가 크게 늘었다.', null, '2026-09-21 22:07:00+09'::timestamptz, false),
  ('trade', '[테스트] 역직구 수출 증가세…특송 통관 물량 역대 최대 수준', '<p>해외 소비자가 국내 온라인몰에서 직접 상품을 구매하는 역직구 수출이 늘면서 특송 화물 통관 물량이 역대 최대 수준을 기록했다. 업계에 따르면 올해 상반기 전자상거래 수출용 특송 화물은 전년 동기 대비 약 27% 증가했다.</p><p>화장품과 패션 잡화, 생활용품이 증가세를 이끈 것으로 분석됐다. F특송업체 관계자는 “일본과 미국, 동남아 소비자의 주문이 고르게 늘고 있다”며 “간이 통관 처리 능력을 높이기 위해 분류 설비를 추가로 도입할 계획”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '해외 소비자가 국내 온라인몰에서 직접 상품을 구매하는 역직구 수출이 늘면서 특송 화물 통관 물량이 역대 최대 수준을 기록했다. 업계에 따르면 올해 상반기 전자상거래 수출용 특송 화물은 전년 동기 대비 약 27% 증가했다.', 'https://picsum.photos/seed/ship-trade-6/800/500', '2026-09-20 00:50:00+09'::timestamptz, true),
  ('trade', '[테스트] FTA 활용률 높인다…중소기업 원산지 실무 교육 확대', '<p>자유무역협정 활용률을 높이기 위해 중소 수출기업을 대상으로 한 원산지 관리 교육 프로그램이 확대되고 있다. A협회는 올해 하반기 지역별 순회 교육을 지난해보다 두 배 늘린 40회 운영하기로 했다고 밝혔다.</p><p>교육은 품목별 원산지 결정 기준, 증빙 서류 보관 방법, 사후 검증 대응 요령 등 실무 중심으로 구성된다. 협회 관계자는 “협정 혜택을 알고도 서류 준비 부담 때문에 활용하지 못하는 기업이 적지 않다”며 “맞춤형 상담도 병행할 예정”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '자유무역협정 활용률을 높이기 위해 중소 수출기업을 대상으로 한 원산지 관리 교육 프로그램이 확대되고 있다. A협회는 올해 하반기 지역별 순회 교육을 지난해보다 두 배 늘린 40회 운영하기로 했다고 밝혔다.', 'https://picsum.photos/seed/ship-trade-7/800/500', '2026-09-18 02:33:00+09'::timestamptz, false),
  ('trade', '[테스트] 미주 노선 운임 안정세…화주들 장기계약 협상 나서', '<p>미주 노선 컨테이너 운임이 최근 안정세를 보이면서 화주들이 선사와의 장기 운송계약 협상에 적극 나서고 있다. 업계에 따르면 내년도 계약을 조기에 확정하려는 대형 화주들의 문의가 지난달부터 눈에 띄게 늘었다.</p><p>물류업계는 운임 수준이 일정 범위에서 유지되는 지금이 계약 조건을 조율하기에 적기라고 보고 있다. G무역업체 물류팀장은 “변동 운임과 고정 운임을 혼합하는 방식으로 위험을 분산하는 방안을 내부적으로 검토하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '미주 노선 컨테이너 운임이 최근 안정세를 보이면서 화주들이 선사와의 장기 운송계약 협상에 적극 나서고 있다. 업계에 따르면 내년도 계약을 조기에 확정하려는 대형 화주들의 문의가 지난달부터 눈에 띄게 늘었다.', 'https://picsum.photos/seed/ship-trade-8/800/500', '2026-09-16 04:16:00+09'::timestamptz, false),
  ('trade', '[테스트] 수출 화물 보험 관심 증가…중소기업 맞춤형 상품 잇따라', '<p>해상 운송 과정의 불확실성이 커지면서 수출 화물 보험에 대한 중소기업의 관심이 높아지고 있다. 업계에 따르면 소량 화물을 수출하는 기업을 겨냥해 보험료 부담을 낮춘 맞춤형 상품이 잇따라 출시되고 있다.</p><p>새 상품들은 온라인으로 선적 건별 가입이 가능하고 보상 절차도 간소화한 것이 특징이다. H보험중개업체 관계자는 “그동안 보험 가입을 비용으로만 여기던 기업들이 필수적인 위험 관리 수단으로 인식을 바꾸고 있다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '해상 운송 과정의 불확실성이 커지면서 수출 화물 보험에 대한 중소기업의 관심이 높아지고 있다. 업계에 따르면 소량 화물을 수출하는 기업을 겨냥해 보험료 부담을 낮춘 맞춤형 상품이 잇따라 출시되고 있다.', 'https://picsum.photos/seed/ship-trade-9/800/500', '2026-09-14 06:59:00+09'::timestamptz, false),
  ('trade', '[테스트] 인도 시장 진출 기업 증가…현지 통관 컨설팅 수요 급증', '<p>인도 시장을 새로운 수출 거점으로 삼으려는 국내 기업이 늘면서 현지 통관 컨설팅 수요가 크게 증가하고 있다. 업계에 따르면 인도향 수출 관련 상담 건수는 올해 들어 전년 대비 30% 가까이 늘어난 것으로 집계됐다.</p><p>기업들은 품목 분류와 인증 절차, 지역별로 다른 행정 관행을 가장 까다로운 부분으로 꼽았다. I컨설팅업체 대표는 “현지 파트너를 통해 사전에 서류 요건을 점검하면 통관 지연과 추가 비용을 상당 부분 줄일 수 있다”고 조언했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '인도 시장을 새로운 수출 거점으로 삼으려는 국내 기업이 늘면서 현지 통관 컨설팅 수요가 크게 증가하고 있다. 업계에 따르면 인도향 수출 관련 상담 건수는 올해 들어 전년 대비 30% 가까이 늘어난 것으로 집계됐다.', null, '2026-09-12 08:42:00+09'::timestamptz, false),
  ('trade', '[테스트] 보세창고 자동화 투자 확대…스마트 물류센터 경쟁 가열', '<p>수도권과 주요 항만 배후단지를 중심으로 보세창고 자동화 투자가 확대되고 있다. 업계에 따르면 자동 분류기와 로봇 피킹 설비를 갖춘 스마트 보세창고는 최근 2년 새 두 배 가까이 늘어난 것으로 파악됐다.</p><p>물류업체들은 전자상거래 수입 화물 증가에 대응해 처리 속도와 정확도를 높이는 데 주력하고 있다. J물류업체 관계자는 “통관 시스템과 창고관리 시스템을 연동해 입고부터 출고까지 걸리는 시간을 기존보다 크게 줄였다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수도권과 주요 항만 배후단지를 중심으로 보세창고 자동화 투자가 확대되고 있다. 업계에 따르면 자동 분류기와 로봇 피킹 설비를 갖춘 스마트 보세창고는 최근 2년 새 두 배 가까이 늘어난 것으로 파악됐다.', 'https://picsum.photos/seed/ship-trade-11/800/500', '2026-09-10 10:25:00+09'::timestamptz, false),
  ('trade', '[테스트] 원자재 조달처 다변화 가속…중동·남미 거래선 확대', '<p>국내 제조기업들이 특정 국가에 대한 원자재 의존도를 낮추기 위해 조달처 다변화에 속도를 내고 있다. 업계에 따르면 중동과 남미 지역에서 원자재를 새로 들여오는 기업이 늘면서 관련 수입 물량도 함께 증가하고 있다.</p><p>조달처가 다양해지면서 물류 경로와 통관 서류도 복잡해지는 추세다. K제조업체 구매담당 임원은 “거래선을 늘리면 비용은 다소 오르지만 공급 차질 위험을 줄일 수 있다”며 “장기적으로는 안정성이 더 중요하다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 제조기업들이 특정 국가에 대한 원자재 의존도를 낮추기 위해 조달처 다변화에 속도를 내고 있다. 업계에 따르면 중동과 남미 지역에서 원자재를 새로 들여오는 기업이 늘면서 관련 수입 물량도 함께 증가하고 있다.', 'https://picsum.photos/seed/ship-trade-12/800/500', '2026-09-08 12:08:00+09'::timestamptz, false),
  ('trade', '[테스트] AI 품목분류 서비스 등장…관세 실무 효율 높인다', '<p>인공지능을 활용해 수출입 물품의 품목 분류를 지원하는 서비스가 잇따라 등장하고 있다. 업계에 따르면 상품 설명과 이미지를 입력하면 적합한 품목번호 후보를 제시하는 방식으로, 관세 실무 현장에서 활용이 늘고 있다.</p><p>관세업계는 반복적인 분류 작업에 드는 시간을 줄이고 전문 인력이 복잡한 사안에 집중할 수 있게 될 것으로 기대하고 있다. L관세법인 관계자는 “최종 판단은 전문가가 하되 검토 속도는 30% 이상 빨라졌다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '인공지능을 활용해 수출입 물품의 품목 분류를 지원하는 서비스가 잇따라 등장하고 있다. 업계에 따르면 상품 설명과 이미지를 입력하면 적합한 품목번호 후보를 제시하는 방식으로, 관세 실무 현장에서 활용이 늘고 있다.', 'https://picsum.photos/seed/ship-trade-13/800/500', '2026-09-06 14:51:00+09'::timestamptz, false),
  ('trade', '[테스트] 수출 바우처 활용 중소기업, 해외 물류비 절감 효과', '<p>수출 지원 바우처를 활용해 해외 물류비를 지원받은 중소기업들이 실질적인 비용 절감 효과를 보고 있는 것으로 나타났다. 업계에 따르면 바우처를 물류 분야에 사용한 기업의 평균 물류비 절감률은 약 18%로 집계됐다.</p><p>기업들은 해외 창고 이용료와 국제 운송비, 통관 대행 수수료 등에 바우처를 주로 활용했다. M수출업체 대표는 “초기 시장 개척 단계에서 물류비 부담을 덜 수 있어 신규 바이어 확보와 현지 마케팅에 집중할 수 있었다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수출 지원 바우처를 활용해 해외 물류비를 지원받은 중소기업들이 실질적인 비용 절감 효과를 보고 있는 것으로 나타났다. 업계에 따르면 바우처를 물류 분야에 사용한 기업의 평균 물류비 절감률은 약 18%로 집계됐다.', 'https://picsum.photos/seed/ship-trade-14/800/500', '2026-09-04 16:34:00+09'::timestamptz, false),
  ('trade', '[테스트] 중앙아시아 경유 운송로 관심 고조…복합운송 상품 출시', '<p>중앙아시아를 경유해 유럽으로 향하는 육상 운송로에 대한 화주들의 관심이 높아지고 있다. 업계에 따르면 해상과 철도를 연계한 복합운송 상품이 잇따라 출시되면서 화주들의 운송 경로 선택지가 넓어지고 있다.</p><p>이 경로는 해상 운송보다 운송 기간이 짧고 항공 운송보다 비용이 낮다는 점이 장점으로 꼽힌다. N포워딩업체 관계자는 “환적 구간의 통관 절차가 안정화되면서 정시성도 꾸준히 개선되고 있다”며 “유럽행 정기 편을 늘릴 계획”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '중앙아시아를 경유해 유럽으로 향하는 육상 운송로에 대한 화주들의 관심이 높아지고 있다. 업계에 따르면 해상과 철도를 연계한 복합운송 상품이 잇따라 출시되면서 화주들의 운송 경로 선택지가 넓어지고 있다.', null, '2026-09-02 18:17:00+09'::timestamptz, false),
  ('trade', '[테스트] 농식품 수출 증가에 콜드체인 물류 수요 확대', '<p>신선 농식품과 가공식품 수출이 늘면서 저온 유통 체계인 콜드체인 물류 수요가 함께 확대되고 있다. 업계에 따르면 올해 냉장·냉동 컨테이너를 이용한 농식품 수출 물량은 전년 대비 약 12% 증가한 것으로 추산됐다.</p><p>물류업체들은 실시간 온도 모니터링 장비와 전용 보관 시설을 확충하며 수요 대응에 나섰다. O농산물수출업체 대표는 “운송 중 품질을 유지하는 것이 재구매로 이어지는 핵심”이라며 “온도 기록 데이터를 바이어와 공유하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '신선 농식품과 가공식품 수출이 늘면서 저온 유통 체계인 콜드체인 물류 수요가 함께 확대되고 있다. 업계에 따르면 올해 냉장·냉동 컨테이너를 이용한 농식품 수출 물량은 전년 대비 약 12% 증가한 것으로 추산됐다.', 'https://picsum.photos/seed/ship-trade-16/800/500', '2026-08-31 21:00:00+09'::timestamptz, false),
  ('trade', '[테스트] 수출입 기업 사이 무역 데이터 플랫폼 도입 확산', '<p>선적 일정과 통관 현황, 운임 정보를 한곳에서 관리할 수 있는 무역 데이터 플랫폼 도입이 수출입 기업 사이에서 확산되고 있다. 업계에 따르면 중견·중소기업을 중심으로 플랫폼 이용 기업 수가 지난해보다 40% 가까이 늘었다.</p><p>기업들은 여러 포워더와 선사로부터 받던 정보를 통합해 실시간으로 확인할 수 있다는 점을 장점으로 꼽았다. P무역업체 관계자는 “화물 위치를 일일이 문의하던 업무가 줄어 담당 인력을 영업 지원에 배치할 수 있게 됐다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '선적 일정과 통관 현황, 운임 정보를 한곳에서 관리할 수 있는 무역 데이터 플랫폼 도입이 수출입 기업 사이에서 확산되고 있다. 업계에 따르면 중견·중소기업을 중심으로 플랫폼 이용 기업 수가 지난해보다 40% 가까이 늘었다.', 'https://picsum.photos/seed/ship-trade-17/800/500', '2026-08-29 22:43:00+09'::timestamptz, false),
  ('trade', '[테스트] 원산지 사후 검증 대비 필요…“증빙 보관 체계 갖춰야”', '<p>자유무역협정 상대국의 원산지 사후 검증 요청이 늘어날 것에 대비해 수출기업들이 증빙 관리 체계를 갖춰야 한다는 지적이 나왔다. 통관 업계 관계자들은 정해진 기간 내 자료를 제출하지 못하면 협정 혜택이 취소될 수 있다고 강조했다.</p><p>전문가들은 원재료 구매 내역과 생산 공정 기록을 체계적으로 보관하는 것이 가장 기본적인 대응이라고 조언했다. Q관세사무소 대표는 “협력업체로부터 받는 원산지 확인서까지 정기적으로 점검하는 습관이 필요하다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '자유무역협정 상대국의 원산지 사후 검증 요청이 늘어날 것에 대비해 수출기업들이 증빙 관리 체계를 갖춰야 한다는 지적이 나왔다. 통관 업계 관계자들은 정해진 기간 내 자료를 제출하지 못하면 협정 혜택이 취소될 수 있다고 강조했다.', 'https://picsum.photos/seed/ship-trade-18/800/500', '2026-08-28 00:26:00+09'::timestamptz, false),
  ('trade', '[테스트] 항공 화물 수요 회복세…반도체·바이오 품목이 견인', '<p>항공 화물 수요가 회복세를 보이는 가운데 반도체 부품과 바이오 의약품 등 고부가가치 품목이 증가세를 이끌고 있다. 업계에 따르면 올해 3분기 국제 항공 화물 처리량은 전년 동기 대비 약 9% 증가한 것으로 집계됐다.</p><p>특히 온도 관리가 필요한 의약품 화물이 늘면서 특수 보관 설비를 갖춘 항공 화물터미널의 이용률이 높아졌다. R항공물류업체 관계자는 “연말 성수기를 앞두고 전세기 운항 일정을 추가로 확보하고 있다”며 “의약품 전용 보관 공간도 늘릴 것”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '항공 화물 수요가 회복세를 보이는 가운데 반도체 부품과 바이오 의약품 등 고부가가치 품목이 증가세를 이끌고 있다. 업계에 따르면 올해 3분기 국제 항공 화물 처리량은 전년 동기 대비 약 9% 증가한 것으로 집계됐다.', 'https://picsum.photos/seed/ship-trade-19/800/500', '2026-08-26 02:09:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 국내 A조선소, LNG운반선 4척 수주…연간 목표 달성 눈앞', '<p>국내 A조선소가 유럽 지역 선주로부터 17만4000㎥급 LNG운반선 4척을 수주했다고 밝혔다. 이번 계약으로 A조선소는 올해 수주 목표의 약 90%를 채우며 연간 목표 조기 달성에 한 걸음 더 다가섰다.</p><p>이번에 수주한 선박은 이중연료 추진 엔진과 재액화 설비를 탑재해 운항 효율을 높인 것이 특징이다. A조선소 관계자는 “친환경 고부가가치 선박 중심의 선별 수주 전략이 성과를 내고 있다”며 “인도는 2029년부터 순차적으로 이뤄질 예정”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 A조선소가 유럽 지역 선주로부터 17만4000㎥급 LNG운반선 4척을 수주했다고 밝혔다. 이번 계약으로 A조선소는 올해 수주 목표의 약 90%를 채우며 연간 목표 조기 달성에 한 걸음 더 다가섰다.', 'https://picsum.photos/seed/ship-shipbuilding-0/800/500', '2026-10-01 07:25:00+09'::timestamptz, true),
  ('shipbuilding', '[테스트] 메탄올 추진 컨테이너선 발주 증가…연료 공급망 구축 과제', '<p>메탄올을 연료로 사용하는 컨테이너선 발주가 꾸준히 늘면서 연료 공급 인프라 구축이 업계의 새로운 과제로 떠오르고 있다. 업계에 따르면 올해 전 세계 신조 컨테이너선 발주 가운데 메탄올 추진선 비중은 약 25%로 추산됐다.</p><p>전문가들은 선박 보급 속도에 비해 항만의 연료 공급 설비 확충이 더디다고 지적했다. B해운컨설팅업체 연구원은 “친환경 메탄올의 안정적인 생산과 벙커링 체계가 함께 갖춰져야 실질적인 탄소 감축 효과를 거둘 수 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '메탄올을 연료로 사용하는 컨테이너선 발주가 꾸준히 늘면서 연료 공급 인프라 구축이 업계의 새로운 과제로 떠오르고 있다. 업계에 따르면 올해 전 세계 신조 컨테이너선 발주 가운데 메탄올 추진선 비중은 약 25%로 추산됐다.', 'https://picsum.photos/seed/ship-shipbuilding-1/800/500', '2026-09-29 09:08:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 암모니아 추진선 실증 속도…기자재 국산화 경쟁 본격화', '<p>무탄소 연료로 주목받는 암모니아를 활용한 선박 추진 기술의 실증이 속도를 내면서 관련 기자재 국산화 경쟁도 본격화하고 있다. 업계에 따르면 국내 기자재업체 여러 곳이 암모니아 연료 공급 장치와 누출 감지 설비 개발에 착수했다.</p><p>암모니아는 독성이 있어 안전 설계가 무엇보다 중요한 것으로 꼽힌다. C기자재업체 연구소장은 “연료 탱크부터 엔진까지 이어지는 배관 전 구간의 안전성을 확보하는 것이 핵심 기술”이라며 “내년 중 시제품 성능 시험을 마칠 계획”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '무탄소 연료로 주목받는 암모니아를 활용한 선박 추진 기술의 실증이 속도를 내면서 관련 기자재 국산화 경쟁도 본격화하고 있다. 업계에 따르면 국내 기자재업체 여러 곳이 암모니아 연료 공급 장치와 누출 감지 설비 개발에 착수했다.', 'https://picsum.photos/seed/ship-shipbuilding-2/800/500', '2026-09-27 11:51:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 자율운항 선박 원격 관제 해상 시험 성공…상용화 한발 더', '<p>국내 연구진과 D조선소가 공동 개발한 자율운항 선박 원격 관제 시스템이 해상 시험에서 성공적인 결과를 거뒀다. 시험 선박은 육상 관제센터의 원격 모니터링 아래 충돌 회피 기동을 포함해 약 120㎞ 구간을 자율 항해했다.</p><p>이번 시험에서는 주변 선박을 인식해 항로를 스스로 조정하는 기능과 통신 지연 상황에서의 안전 대응 기능이 함께 검증됐다. D조선소 관계자는 “국제 기준 논의 흐름에 맞춰 단계적으로 상용화 수준의 기술을 확보해 나갈 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 연구진과 D조선소가 공동 개발한 자율운항 선박 원격 관제 시스템이 해상 시험에서 성공적인 결과를 거뒀다. 시험 선박은 육상 관제센터의 원격 모니터링 아래 충돌 회피 기동을 포함해 약 120㎞ 구간을 자율 항해했다.', 'https://picsum.photos/seed/ship-shipbuilding-3/800/500', '2026-09-25 13:34:00+09'::timestamptz, true),
  ('shipbuilding', '[테스트] 해양 기자재업계, 친환경 설비 수주 증가로 실적 개선', '<p>국내 해양 기자재업계가 친환경 선박 설비 수주 증가에 힘입어 실적 개선 흐름을 이어가고 있다. 업계에 따르면 주요 기자재업체들의 올해 상반기 친환경 설비 관련 매출은 전년 동기 대비 평균 20% 이상 늘어난 것으로 파악됐다.</p><p>이중연료 엔진 부품, 배기가스 처리 장치, 선박용 배터리 시스템 등이 성장세를 이끌었다. E기자재업체 대표는 “조선소 수주 증가가 협력업체로 이어지는 선순환이 나타나고 있다”며 “생산 설비 증설을 검토하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 해양 기자재업계가 친환경 선박 설비 수주 증가에 힘입어 실적 개선 흐름을 이어가고 있다. 업계에 따르면 주요 기자재업체들의 올해 상반기 친환경 설비 관련 매출은 전년 동기 대비 평균 20% 이상 늘어난 것으로 파악됐다.', null, '2026-09-23 15:17:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 조선업계 인력 확보 총력…현장 맞춤형 교육 과정 확대', '<p>수주 증가로 일감이 늘어난 조선업계가 생산 인력 확보를 위해 현장 맞춤형 교육 과정을 확대하고 있다. 업계에 따르면 주요 조선소와 지역 교육기관이 연계한 용접·도장 분야 인력 양성 과정 정원은 올해 30% 가까이 늘었다.</p><p>교육 과정은 이론 수업과 함께 실제 작업장과 유사한 환경에서의 실습 비중을 높인 것이 특징이다. F조선소 인사담당자는 “숙련 인력이 현장에 안착할 수 있도록 교육 수료 이후 멘토링 프로그램도 함께 운영하고 있다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수주 증가로 일감이 늘어난 조선업계가 생산 인력 확보를 위해 현장 맞춤형 교육 과정을 확대하고 있다. 업계에 따르면 주요 조선소와 지역 교육기관이 연계한 용접·도장 분야 인력 양성 과정 정원은 올해 30% 가까이 늘었다.', 'https://picsum.photos/seed/ship-shipbuilding-5/800/500', '2026-09-21 18:00:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 해상풍력 설치선 수요 증가…국내 조선소 수주 기대감', '<p>세계 각국의 해상풍력 발전 단지 조성이 확대되면서 대형 풍력 설비를 바다에 설치하는 전용 선박 수요도 늘고 있다. 업계에 따르면 향후 5년간 전 세계적으로 수십 척 규모의 해상풍력 설치선 발주가 이뤄질 것으로 전망된다.</p><p>국내 조선소들은 고난도 해양 구조물 건조 경험을 바탕으로 수주 기회를 모색하고 있다. G조선소 영업담당 임원은 “대형 크레인과 위치 유지 장치 등 핵심 설비 통합 역량에서 경쟁력이 있다”며 “유럽과 아시아 선주들과 협의를 이어가고 있다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '세계 각국의 해상풍력 발전 단지 조성이 확대되면서 대형 풍력 설비를 바다에 설치하는 전용 선박 수요도 늘고 있다. 업계에 따르면 향후 5년간 전 세계적으로 수십 척 규모의 해상풍력 설치선 발주가 이뤄질 것으로 전망된다.', 'https://picsum.photos/seed/ship-shipbuilding-6/800/500', '2026-09-19 19:43:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] IMO 환경규제 강화 앞두고 노후 선박 교체 수요 확대', '<p>국제해사기구(IMO)의 온실가스 감축 규제 강화를 앞두고 노후 선박을 친환경 선박으로 교체하려는 수요가 확대되고 있다. 업계에 따르면 선령 15년 이상 선박을 운영하는 선사들을 중심으로 신조 발주 문의가 지난해보다 크게 늘었다.</p><p>선사들은 규제 대응 비용과 연료 효율 개선 효과를 종합적으로 따져 교체 시기를 저울질하고 있다. H해운업체 관계자는 “당장 신조가 어려운 선박은 에너지 절감 장치를 추가로 장착하는 방안도 함께 검토하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국제해사기구(IMO)의 온실가스 감축 규제 강화를 앞두고 노후 선박을 친환경 선박으로 교체하려는 수요가 확대되고 있다. 업계에 따르면 선령 15년 이상 선박을 운영하는 선사들을 중심으로 신조 발주 문의가 지난해보다 크게 늘었다.', 'https://picsum.photos/seed/ship-shipbuilding-7/800/500', '2026-09-17 21:26:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 디지털 트윈 기반 스마트 조선소 구축 가속', '<p>국내 조선업계가 생산 공정 전반을 가상 공간에 구현하는 디지털 트윈 기술을 도입하며 스마트 조선소 구축에 속도를 내고 있다. 업계에 따르면 설계부터 건조, 시운전까지 데이터를 연결해 공정 지연을 사전에 예측하는 시스템이 확산되고 있다.</p><p>조선소들은 이를 통해 블록 이동 동선을 최적화하고 자재 낭비를 줄이는 효과를 거두고 있다. I조선소 생산기술팀장은 “가상 시뮬레이션으로 작업 순서를 미리 검증하면서 일부 공정의 작업 시간이 15%가량 단축됐다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 조선업계가 생산 공정 전반을 가상 공간에 구현하는 디지털 트윈 기술을 도입하며 스마트 조선소 구축에 속도를 내고 있다. 업계에 따르면 설계부터 건조, 시운전까지 데이터를 연결해 공정 지연을 사전에 예측하는 시스템이 확산되고 있다.', 'https://picsum.photos/seed/ship-shipbuilding-8/800/500', '2026-09-15 23:09:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 중형 조선소, 친환경 탱커 수주로 안정적 일감 확보', '<p>국내 중형 조선소들이 친환경 사양을 적용한 중형 탱커 수주를 잇따라 따내며 안정적인 일감을 확보하고 있다. 업계에 따르면 J조선소는 최근 아시아 지역 선주와 5만t급 석유화학제품운반선 6척에 대한 건조 계약을 체결했다.</p><p>이번 선박에는 향후 메탄올 연료 전환이 가능한 설계가 적용될 예정이다. J조선소 관계자는 “대형 조선소와 차별화된 선종에 집중한 전략이 효과를 보고 있다”며 “2년 이상의 건조 물량을 확보해 경영 안정성이 높아졌다”고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국내 중형 조선소들이 친환경 사양을 적용한 중형 탱커 수주를 잇따라 따내며 안정적인 일감을 확보하고 있다. 업계에 따르면 J조선소는 최근 아시아 지역 선주와 5만t급 석유화학제품운반선 6척에 대한 건조 계약을 체결했다.', null, '2026-09-14 01:52:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 선박용 수소 연료전지 개발 박차…중소형 선박 적용 추진', '<p>수소를 활용한 선박용 연료전지 시스템 개발이 활발해지면서 중소형 선박을 중심으로 실제 적용이 추진되고 있다. 업계에 따르면 K기자재업체는 연안 여객선과 작업선에 탑재할 수 있는 수백㎾급 연료전지 모듈 개발을 진행하고 있다.</p><p>연료전지 선박은 운항 중 배출가스와 소음이 적어 항만 인근을 오가는 선박에 적합하다는 평가를 받는다. K기자재업체 관계자는 “수소 저장과 공급 안전성 검증을 마무리한 뒤 내후년 실선 적용을 목표로 하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수소를 활용한 선박용 연료전지 시스템 개발이 활발해지면서 중소형 선박을 중심으로 실제 적용이 추진되고 있다. 업계에 따르면 K기자재업체는 연안 여객선과 작업선에 탑재할 수 있는 수백㎾급 연료전지 모듈 개발을 진행하고 있다.', 'https://picsum.photos/seed/ship-shipbuilding-10/800/500', '2026-09-12 03:35:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 해양플랜트 시장 회복 조짐…부유식 설비 발주 검토 늘어', '<p>한동안 정체됐던 해양플랜트 시장이 회복 조짐을 보이면서 부유식 생산설비 발주를 검토하는 사례가 늘고 있다. 업계에 따르면 해외 에너지 기업들의 해양 가스전 개발 계획이 재가동되면서 관련 입찰 문의가 증가했다.</p><p>국내 조선업계는 과거 경험을 바탕으로 수익성을 꼼꼼히 따지는 선별 수주 기조를 유지하고 있다. L조선소 관계자는 “설계 표준화와 공정 관리 역량을 높여 원가 위험을 줄이는 방향으로 입찰을 준비하고 있다”고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '한동안 정체됐던 해양플랜트 시장이 회복 조짐을 보이면서 부유식 생산설비 발주를 검토하는 사례가 늘고 있다. 업계에 따르면 해외 에너지 기업들의 해양 가스전 개발 계획이 재가동되면서 관련 입찰 문의가 증가했다.', 'https://picsum.photos/seed/ship-shipbuilding-11/800/500', '2026-09-10 05:18:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 선박용 탄소 포집 장치 실증 착수…상용화 가능성 주목', '<p>운항 중인 선박에서 배출되는 이산화탄소를 직접 포집해 저장하는 선박용 탄소 포집 장치의 실증이 시작됐다. 업계에 따르면 M기자재업체는 중형 컨테이너선에 시험 장치를 설치하고 약 6개월간 성능을 검증할 계획이다.</p><p>업계는 대체 연료 전환이 본격화하기 전까지 기존 선박의 배출량을 줄이는 현실적인 대안이 될 수 있다고 보고 있다. M기자재업체 연구원은 “포집 효율과 함께 저장 공간 확보, 하역 절차까지 종합적으로 검증할 것”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '운항 중인 선박에서 배출되는 이산화탄소를 직접 포집해 저장하는 선박용 탄소 포집 장치의 실증이 시작됐다. 업계에 따르면 M기자재업체는 중형 컨테이너선에 시험 장치를 설치하고 약 6개월간 성능을 검증할 계획이다.', 'https://picsum.photos/seed/ship-shipbuilding-12/800/500', '2026-09-08 07:01:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 조선소, 기자재 공급망 안정 위해 협력사 상생 지원 확대', '<p>조선소들이 기자재 공급망 안정화를 위해 협력업체와의 상생 프로그램을 확대하고 있다. 업계에 따르면 N조선소는 주요 협력사를 대상으로 설비 투자 자금 지원과 기술 교육, 장기 공급 계약을 묶은 지원 패키지를 마련했다.</p><p>수주 물량이 늘면서 기자재 납기 관리가 건조 일정의 핵심 변수로 떠오른 데 따른 조치다. N조선소 구매담당 임원은 “협력사의 생산 능력이 곧 조선소의 경쟁력”이라며 “품질과 납기를 함께 끌어올릴 수 있도록 지원을 지속할 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '조선소들이 기자재 공급망 안정화를 위해 협력업체와의 상생 프로그램을 확대하고 있다. 업계에 따르면 N조선소는 주요 협력사를 대상으로 설비 투자 자금 지원과 기술 교육, 장기 공급 계약을 묶은 지원 패키지를 마련했다.', 'https://picsum.photos/seed/ship-shipbuilding-13/800/500', '2026-09-06 09:44:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 친환경 어선 보급 시동…전기 추진 소형 어선 시범 운항', '<p>연안 어업 분야에서도 친환경 선박 전환이 시작되면서 전기 추진 소형 어선이 시범 운항에 들어갔다. 업계에 따르면 O조선업체가 건조한 10t급 전기 추진 어선은 배터리 완충 시 하루 조업에 필요한 운항 거리를 충분히 소화하는 것으로 나타났다.</p><p>시범 운항에 참여한 어업인들은 소음과 진동이 적어 작업 환경이 개선됐다는 반응을 보였다. O조선업체 대표는 “항구별 충전 설비가 함께 갖춰지면 보급 속도가 빨라질 것”이라며 “하이브리드 모델 개발도 병행하고 있다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '연안 어업 분야에서도 친환경 선박 전환이 시작되면서 전기 추진 소형 어선이 시범 운항에 들어갔다. 업계에 따르면 O조선업체가 건조한 10t급 전기 추진 어선은 배터리 완충 시 하루 조업에 필요한 운항 거리를 충분히 소화하는 것으로 나타났다.', null, '2026-09-04 11:27:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] LNG 벙커링선 수요 증가…아시아 항만 연료 공급 경쟁', '<p>LNG 추진 선박이 늘어나면서 선박에 연료를 공급하는 LNG 벙커링선 수요도 함께 증가하고 있다. 업계에 따르면 싱가포르와 중국, 일본 등 아시아 주요 항만들이 연료 공급 능력 확대에 나서면서 관련 선박 발주가 이어지고 있다.</p><p>국내 조선소들은 화물창 기술과 연료 이송 설비 통합 역량을 앞세워 수주전에 뛰어들고 있다. P조선소 관계자는 “벙커링선은 규모는 작지만 기술 난도가 높아 국내 조선소가 경쟁력을 발휘할 수 있는 선종”이라고 설명했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'LNG 추진 선박이 늘어나면서 선박에 연료를 공급하는 LNG 벙커링선 수요도 함께 증가하고 있다. 업계에 따르면 싱가포르와 중국, 일본 등 아시아 주요 항만들이 연료 공급 능력 확대에 나서면서 관련 선박 발주가 이어지고 있다.', 'https://picsum.photos/seed/ship-shipbuilding-15/800/500', '2026-09-02 13:10:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 선박 설계에 인공지능 도입…초기 설계 기간 대폭 단축', '<p>조선업계가 인공지능을 선박 초기 설계 단계에 도입하면서 설계 기간 단축 효과를 거두고 있다. 업계에 따르면 Q조선소는 과거 건조 데이터를 학습한 설계 지원 시스템을 활용해 선형 검토 기간을 기존보다 40%가량 줄였다.</p><p>시스템은 선주의 요구 조건을 입력하면 연비와 적재 효율을 고려한 선형 후보를 자동으로 제시한다. Q조선소 설계담당 임원은 “설계자가 반복 작업 대신 최적안 검토에 집중할 수 있게 됐다”며 “견적 대응 속도도 빨라졌다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '조선업계가 인공지능을 선박 초기 설계 단계에 도입하면서 설계 기간 단축 효과를 거두고 있다. 업계에 따르면 Q조선소는 과거 건조 데이터를 학습한 설계 지원 시스템을 활용해 선형 검토 기간을 기존보다 40%가량 줄였다.', 'https://picsum.photos/seed/ship-shipbuilding-16/800/500', '2026-08-31 15:53:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 극지 항로 대비 쇄빙 기능 선박 기술 개발 활발', '<p>북극 항로 활용 가능성이 거론되면서 얼음을 깨며 운항할 수 있는 쇄빙 기능 선박 기술 개발이 활발해지고 있다. 업계에 따르면 국내 연구기관과 R조선소는 저온 환경에 강한 선체 소재와 결빙 방지 설비를 공동 연구하고 있다.</p><p>극지 운항 선박은 혹한 환경에서도 장비가 정상 작동하도록 설계하는 것이 관건이다. R조선소 연구원은 “선체 강도와 추진 효율을 동시에 확보하는 기술을 축적하고 있다”며 “특수선 시장에서 새로운 기회가 될 것”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '북극 항로 활용 가능성이 거론되면서 얼음을 깨며 운항할 수 있는 쇄빙 기능 선박 기술 개발이 활발해지고 있다. 업계에 따르면 국내 연구기관과 R조선소는 저온 환경에 강한 선체 소재와 결빙 방지 설비를 공동 연구하고 있다.', 'https://picsum.photos/seed/ship-shipbuilding-17/800/500', '2026-08-29 17:36:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 선박 수리·개조 시장 성장세…친환경 개조 수요가 견인', '<p>기존 선박에 친환경 설비를 추가하는 개조 수요가 늘면서 선박 수리·개조 시장이 성장세를 보이고 있다. 업계에 따르면 연료 전환 대비 개조와 에너지 절감 장치 설치 작업이 전체 수리 물량에서 차지하는 비중이 30%를 넘어섰다.</p><p>국내 수리조선업계는 개조 설계 역량과 공기 단축을 내세워 해외 선주 유치에 나서고 있다. S수리조선업체 대표는 “신조선 대비 투자 부담이 적어 선주들의 관심이 높다”며 “도크 운영 효율을 높여 처리 능력을 늘릴 계획”이라고 밝혔다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '기존 선박에 친환경 설비를 추가하는 개조 수요가 늘면서 선박 수리·개조 시장이 성장세를 보이고 있다. 업계에 따르면 연료 전환 대비 개조와 에너지 절감 장치 설치 작업이 전체 수리 물량에서 차지하는 비중이 30%를 넘어섰다.', 'https://picsum.photos/seed/ship-shipbuilding-18/800/500', '2026-08-27 19:19:00+09'::timestamptz, false),
  ('shipbuilding', '[테스트] 해양 관측 무인 수상정 개발…해양 데이터 산업 확대', '<p>바다의 수온과 염분, 해류 정보를 자동으로 수집하는 무인 수상정 개발이 활발해지면서 해양 데이터 산업이 확대되고 있다. 업계에 따르면 T해양장비업체는 태양광 충전 방식으로 수개월간 연속 운용이 가능한 관측용 무인 수상정을 개발했다.</p><p>수집된 데이터는 해양 환경 연구와 항로 안전 정보, 수산 자원 관리 등에 폭넓게 활용될 수 있다. T해양장비업체 관계자는 “여러 대의 무인 수상정을 연계 운용하는 군집 관측 기술도 개발하고 있다”며 “내년 중 시범 서비스를 시작할 계획”이라고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '바다의 수온과 염분, 해류 정보를 자동으로 수집하는 무인 수상정 개발이 활발해지면서 해양 데이터 산업이 확대되고 있다. 업계에 따르면 T해양장비업체는 태양광 충전 방식으로 수개월간 연속 운용이 가능한 관측용 무인 수상정을 개발했다.', null, '2026-08-25 21:02:00+09'::timestamptz, false),
  ('people', '[테스트] A물류협회, 제12대 신임 회장에 업계 원로 선출', '<p>A물류협회는 1일 서울 여의도에서 정기총회를 열고 제12대 신임 회장으로 30년 경력의 종합물류기업 대표를 만장일치로 선출했다. 신임 회장은 앞으로 3년간 협회를 이끌며 회원사 권익 보호와 산업 경쟁력 강화에 나선다.</p><p>신임 회장은 취임 일성으로 “중소 회원사의 디지털 전환과 인력 확보를 최우선 과제로 삼겠다”고 밝혔다. 협회는 이날 총회에서 부회장 4명과 감사 2명도 새로 선임하고, 내년도 사업계획과 예산안을 원안대로 의결했다. 신임 회장의 공식 임기는 다음 달 1일부터 시작된다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'A물류협회는 1일 서울 여의도에서 정기총회를 열고 제12대 신임 회장으로 30년 경력의 종합물류기업 대표를 만장일치로 선출했다. 신임 회장은 앞으로 3년간 협회를 이끌며 회원사 권익 보호와 산업 경쟁력 강화에 나선다.', 'https://picsum.photos/seed/ship-people-0/800/500', '2026-10-01 02:18:00+09'::timestamptz, true),
  ('people', '[테스트] B선사, 신임 대표이사에 내부 출신 영업통 선임', '<p>중견 컨테이너선사인 B선사는 이사회를 열고 신임 대표이사로 영업본부장을 맡아온 내부 인사를 선임했다고 밝혔다. 신임 대표는 입사 후 25년간 아주 항로 영업과 신규 노선 개설을 담당해 온 정통 영업 전문가로 꼽힌다.</p><p>B선사는 이번 인사가 운임 변동성이 커진 시장 환경에서 화주 네트워크를 강화하기 위한 결정이라고 설명했다. 신임 대표는 “기존 고객과의 신뢰를 바탕으로 동남아 신규 서비스를 단계적으로 확대하겠다”고 말했다. 신임 대표의 임기는 3년이다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '중견 컨테이너선사인 B선사는 이사회를 열고 신임 대표이사로 영업본부장을 맡아온 내부 인사를 선임했다고 밝혔다. 신임 대표는 입사 후 25년간 아주 항로 영업과 신규 노선 개설을 담당해 온 정통 영업 전문가로 꼽힌다.', 'https://picsum.photos/seed/ship-people-1/800/500', '2026-09-29 04:01:00+09'::timestamptz, false),
  ('people', '[테스트] C포워딩 대표, 국제 물류포럼서 기조연설', '<p>C포워딩 대표가 싱가포르에서 열린 국제 물류포럼에 연사로 초청돼 ‘아시아 공급망 재편과 포워더의 역할’을 주제로 기조연설을 했다. 이번 포럼에는 20여 개국 물류기업 관계자 600여 명이 참석했다.</p><p>C포워딩 대표는 연설에서 “공급망 다변화 국면에서 포워더는 단순 운송 대행을 넘어 리스크 관리 파트너가 돼야 한다”고 강조했다. 이어 실시간 화물 추적과 데이터 기반 운임 예측 사례를 소개해 참석자들의 관심을 모았다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'C포워딩 대표가 싱가포르에서 열린 국제 물류포럼에 연사로 초청돼 ‘아시아 공급망 재편과 포워더의 역할’을 주제로 기조연설을 했다. 이번 포럼에는 20여 개국 물류기업 관계자 600여 명이 참석했다.', 'https://picsum.photos/seed/ship-people-2/800/500', '2026-09-27 06:44:00+09'::timestamptz, false),
  ('people', '[테스트] D항만운영사, 정기 임원 인사로 운영본부 세대교체', '<p>부산항 신항에서 컨테이너터미널을 운영하는 D항만운영사가 2027년도 정기 임원 인사를 단행했다. 이번 인사에서는 운영본부장과 안전관리실장 등 핵심 보직에 40대 후반 임원이 대거 발탁됐다.</p><p>회사 측은 터미널 자동화 전환을 앞두고 현장 경험과 디지털 역량을 겸비한 인재를 전진 배치했다고 설명했다. 이와 함께 친환경 장비 도입을 전담할 녹색전환 태스크포스를 신설하고 상무급 책임자를 임명했다. 신임 임원들의 임기는 내년 1월 1일부터 시작된다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '부산항 신항에서 컨테이너터미널을 운영하는 D항만운영사가 2027년도 정기 임원 인사를 단행했다. 이번 인사에서는 운영본부장과 안전관리실장 등 핵심 보직에 40대 후반 임원이 대거 발탁됐다.', null, '2026-09-25 08:27:00+09'::timestamptz, false),
  ('people', '[테스트] E항공화물 서비스사, 인천 지사장에 화물 운영 전문가 부임', '<p>항공화물 판매대리점인 E항공화물 서비스사는 인천공항 지사장에 항공사 화물 운영 부문 출신 전문가를 신규 선임했다고 밝혔다. 신임 지사장은 20년 가까이 항공화물 스페이스 관리와 특수화물 운송을 담당해 왔다.</p><p>E사는 전자상거래 화물과 의약품 등 고부가가치 화물 수요 증가에 대응하기 위해 이번 인사를 결정했다. 신임 지사장은 “인천공항 화물터미널 인근 파트너사와 협력해 화물 처리 시간을 줄이는 데 주력하겠다”고 말했다. E사는 연내 인천 화물 전담 인력도 30% 늘릴 계획이다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '항공화물 판매대리점인 E항공화물 서비스사는 인천공항 지사장에 항공사 화물 운영 부문 출신 전문가를 신규 선임했다고 밝혔다. 신임 지사장은 20년 가까이 항공화물 스페이스 관리와 특수화물 운송을 담당해 왔다.', 'https://picsum.photos/seed/ship-people-4/800/500', '2026-09-23 10:10:00+09'::timestamptz, false),
  ('people', '[테스트] F해운중개협회, 정기총회서 회칙 개정안 의결', '<p>F해운중개협회는 지난달 30일 부산에서 정기총회를 열고 회원 자격 요건을 완화하는 회칙 개정안을 의결했다. 이날 총회에는 회원사 대표와 관계자 80여 명이 참석해 협회 운영 방향과 내년도 주요 사업을 논의했다.</p><p>개정 회칙에 따라 설립 3년 미만 신생 중개업체도 준회원으로 가입할 수 있게 됐다. 협회는 또 회원사 실무자를 대상으로 용선계약과 선박 매매 실무 교육 과정을 연 2회 정례화하기로 했다. 내년 상반기에는 해외 중개업 단체와의 교류 행사도 추진한다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'F해운중개협회는 지난달 30일 부산에서 정기총회를 열고 회원 자격 요건을 완화하는 회칙 개정안을 의결했다. 이날 총회에는 회원사 대표와 관계자 80여 명이 참석해 협회 운영 방향과 내년도 주요 사업을 논의했다.', 'https://picsum.photos/seed/ship-people-5/800/500', '2026-09-21 12:53:00+09'::timestamptz, false),
  ('people', '[테스트] G물류, 물류혁신대상서 스마트창고 부문 대상 수상', '<p>G물류가 물류업계 단체들이 공동 주관한 올해 물류혁신대상 시상식에서 스마트창고 부문 대상을 받았다. G물류는 자동 분류 설비와 로봇 피킹 시스템을 결합한 경기 남부 물류센터 운영 성과를 인정받았다.</p><p>심사위원회는 G물류가 센터 출고 정확도를 99.9% 수준으로 끌어올리고 작업자 이동 거리를 40% 줄인 점을 높이 평가했다. G물류 대표는 수상 소감에서 “현장 직원들의 아이디어가 만든 결과”라며 공을 돌렸다. G물류는 같은 시스템을 충청권 센터에도 도입할 방침이다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'G물류가 물류업계 단체들이 공동 주관한 올해 물류혁신대상 시상식에서 스마트창고 부문 대상을 받았다. G물류는 자동 분류 설비와 로봇 피킹 시스템을 결합한 경기 남부 물류센터 운영 성과를 인정받았다.', 'https://picsum.photos/seed/ship-people-6/800/500', '2026-09-19 14:36:00+09'::timestamptz, false),
  ('people', '[테스트] H터미널·I선사, 친환경 하역 협력 업무협약 체결', '<p>H터미널과 I선사는 광양항 터미널 회의실에서 친환경 하역 체계 구축을 위한 업무협약을 체결했다고 밝혔다. 협약식에는 양사 대표와 실무 임원 10여 명이 참석해 향후 협력 일정과 세부 과제를 확인했다.</p><p>양사는 협약에 따라 선박 정박 중 육상전원공급설비 활용률을 높이고 전기 야드트랙터 운영을 확대하기로 했다. 또 하역 과정에서 발생하는 탄소배출량을 공동으로 측정해 매년 결과를 공유할 계획이다. 성과 점검을 위한 분기별 실무 협의회도 정례화한다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'H터미널과 I선사는 광양항 터미널 회의실에서 친환경 하역 체계 구축을 위한 업무협약을 체결했다고 밝혔다. 협약식에는 양사 대표와 실무 임원 10여 명이 참석해 향후 협력 일정과 세부 과제를 확인했다.', 'https://picsum.photos/seed/ship-people-7/800/500', '2026-09-17 16:19:00+09'::timestamptz, false),
  ('people', '[테스트] J창고, 최고재무책임자에 금융권 출신 전문가 영입', '<p>물류센터 임대·운영 전문기업인 J창고는 신임 최고재무책임자로 금융권에서 부동산 금융을 담당해 온 전문가를 영입했다고 밝혔다. 신임 CFO는 다음 달 1일부터 재무와 투자 업무를 총괄한다.</p><p>J창고는 수도권과 충청권에 신규 물류센터 3곳을 개발하는 계획을 추진 중이며 이번 영입으로 자금 조달 역량을 강화할 방침이다. 회사 측은 “안정적인 재무 구조를 바탕으로 장기 성장 기반을 다지겠다”고 밝혔다. 신임 CFO는 자산운용사와 은행에서 20년 넘게 근무했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '물류센터 임대·운영 전문기업인 J창고는 신임 최고재무책임자로 금융권에서 부동산 금융을 담당해 온 전문가를 영입했다고 밝혔다. 신임 CFO는 다음 달 1일부터 재무와 투자 업무를 총괄한다.', null, '2026-09-15 18:02:00+09'::timestamptz, false),
  ('people', '[테스트] K해운, ESG위원회 신설하고 외부 전문가 위원장 위촉', '<p>K해운은 이사회 산하에 ESG위원회를 신설하고 초대 위원장으로 환경 경영 분야 외부 전문가를 위촉했다고 밝혔다. 위원회는 사외이사 3명과 사내이사 1명 등 모두 4명으로 구성된다.</p><p>ESG위원회는 앞으로 선대 탈탄소 전략과 선원 안전, 지배구조 개선 과제를 분기마다 점검한다. K해운은 위원회 논의 결과를 반영해 내년 상반기 첫 지속가능경영보고서를 발간할 계획이다. 위원회 첫 회의는 다음 달 중순 본사에서 열린다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'K해운은 이사회 산하에 ESG위원회를 신설하고 초대 위원장으로 환경 경영 분야 외부 전문가를 위촉했다고 밝혔다. 위원회는 사외이사 3명과 사내이사 1명 등 모두 4명으로 구성된다.', 'https://picsum.photos/seed/ship-people-9/800/500', '2026-09-13 20:45:00+09'::timestamptz, false),
  ('people', '[테스트] L포워더협회, 청년위원회 출범식 열고 활동 개시', '<p>L포워더협회는 서울 중구 협회 회의실에서 청년위원회 출범식을 열고 본격적인 대외 활동에 들어갔다. 청년위원회는 회원사에 근무하는 30대 젊은 실무자와 2세 경영인 등 25명으로 구성됐다.</p><p>초대 청년위원장에는 중견 포워딩업체 기획팀장이 선임됐다. 위원회는 업계 이미지 개선과 신규 인력 유입을 위해 대학생 대상 물류 직무 설명회와 현직자 멘토링 프로그램을 운영할 예정이다. 첫 설명회는 다음 달 부산과 인천의 대학 두 곳에서 열린다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'L포워더협회는 서울 중구 협회 회의실에서 청년위원회 출범식을 열고 본격적인 대외 활동에 들어갔다. 청년위원회는 회원사에 근무하는 30대 젊은 실무자와 2세 경영인 등 25명으로 구성됐다.', 'https://picsum.photos/seed/ship-people-10/800/500', '2026-09-11 22:28:00+09'::timestamptz, false),
  ('people', '[테스트] M선박관리 대표, 해양환경 세미나서 탄소감축 사례 발표', '<p>M선박관리 대표가 부산에서 열린 해양환경 세미나에 발표자로 참석해 운항 선박의 탄소집약도 개선 사례를 소개했다. 세미나는 IMO 환경규제 대응 전략을 주제로 선사와 조선소 관계자 200여 명이 참석한 가운데 진행됐다.</p><p>M선박관리 대표는 관리 선박에 저마찰 도료와 최적 항로 시스템을 적용해 연료 소모를 평균 8% 줄였다고 설명했다. 그는 “규제 대응은 비용이 아니라 운항 효율을 높이는 기회”라고 말했다. 발표 자료는 세미나 참석자들에게 별도로 배포됐다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'M선박관리 대표가 부산에서 열린 해양환경 세미나에 발표자로 참석해 운항 선박의 탄소집약도 개선 사례를 소개했다. 세미나는 IMO 환경규제 대응 전략을 주제로 선사와 조선소 관계자 200여 명이 참석한 가운데 진행됐다.', 'https://picsum.photos/seed/ship-people-11/800/500', '2026-09-10 00:11:00+09'::timestamptz, false),
  ('people', '[테스트] N물류, 부산 신사옥 개소식 열고 남부권 영업 강화', '<p>N물류는 부산 중앙동에 신사옥을 마련하고 협력사와 고객사 관계자 100여 명이 참석한 가운데 개소식을 열었다. 신사옥에는 영남권 영업본부와 해상 운영팀, 통관 지원 조직이 함께 입주했다.</p><p>N물류는 신사옥 이전을 계기로 부산항을 거점으로 하는 수출입 화물 유치에 속도를 낼 계획이다. 대표는 개소식 인사말에서 “고객과 가까운 곳에서 더 빠르게 응답하는 물류 파트너가 되겠다”고 밝혔다. 신사옥은 지상 8층 규모로 교육장과 고객 상담실도 갖췄다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'N물류는 부산 중앙동에 신사옥을 마련하고 협력사와 고객사 관계자 100여 명이 참석한 가운데 개소식을 열었다. 신사옥에는 영남권 영업본부와 해상 운영팀, 통관 지원 조직이 함께 입주했다.', 'https://picsum.photos/seed/ship-people-12/800/500', '2026-09-08 02:54:00+09'::timestamptz, false),
  ('people', '[테스트] O콜드체인 대표, 업계 단체 연례 시상식서 공로상 수상', '<p>O콜드체인 대표가 한 물류업계 단체가 주관한 연례 시상식에서 올해 산업 발전 공로상을 받았다. 이 상은 냉장·냉동 물류 분야의 품질 기준 정립과 인력 양성에 기여한 업계 인물에게 매년 수여된다.</p><p>O콜드체인 대표는 지난 10여 년간 온도 기록 관리 표준안 마련과 중소 냉동창고 대상 무료 교육에 앞장서 왔다. 그는 “상금 전액을 업계 청년 인재 장학 사업에 기부하겠다”고 밝혔다. 시상식에는 업계 관계자 200여 명이 참석해 수상을 축하했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'O콜드체인 대표가 한 물류업계 단체가 주관한 연례 시상식에서 올해 산업 발전 공로상을 받았다. 이 상은 냉장·냉동 물류 분야의 품질 기준 정립과 인력 양성에 기여한 업계 인물에게 매년 수여된다.', null, '2026-09-06 04:37:00+09'::timestamptz, false),
  ('people', '[테스트] P관세법인, 신임 대표에 통관 실무 30년 관세사 취임', '<p>P관세법인은 신임 대표로 30년간 수출입 통관 실무를 담당해 온 관세사가 취임했다고 밝혔다. 신임 대표는 전자상거래 통관과 원산지 관리 분야에서 풍부한 경험을 쌓아 온 것으로 알려졌다.</p><p>신임 대표는 취임사에서 “자유무역협정 활용 컨설팅을 강화해 중소 수출기업의 관세 부담을 줄이는 데 힘쓰겠다”고 말했다. P관세법인은 올해 안에 평택과 인천에 분사무소를 추가로 열 계획이다. 신임 대표는 다음 주부터 주요 고객사를 차례로 방문할 예정이다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'P관세법인은 신임 대표로 30년간 수출입 통관 실무를 담당해 온 관세사가 취임했다고 밝혔다. 신임 대표는 전자상거래 통관과 원산지 관리 분야에서 풍부한 경험을 쌓아 온 것으로 알려졌다.', 'https://picsum.photos/seed/ship-people-14/800/500', '2026-09-04 06:20:00+09'::timestamptz, false),
  ('people', '[테스트] Q해운, 인천 지점 개설하고 신임 지점장 발령', '<p>Q해운이 인천항 물동량 증가에 대응하기 위해 인천 지점을 새로 개설하고 신임 지점장을 발령했다. 신임 지점장은 본사에서 한중 항로 운영과 화주 영업을 맡아 온 15년 경력의 실무자다.</p><p>인천 지점은 한중 카페리 화물과 근해 컨테이너 서비스의 현지 영업을 전담한다. Q해운은 지점 개설을 계기로 수도권 화주에게 선적 예약부터 서류 처리까지 한곳에서 지원하는 서비스를 제공할 방침이다. 인천 지점은 인천항 인근 업무지구에 문을 열었다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'Q해운이 인천항 물동량 증가에 대응하기 위해 인천 지점을 새로 개설하고 신임 지점장을 발령했다. 신임 지점장은 본사에서 한중 항로 운영과 화주 영업을 맡아 온 15년 경력의 실무자다.', 'https://picsum.photos/seed/ship-people-15/800/500', '2026-09-02 08:03:00+09'::timestamptz, false),
  ('people', '[테스트] R물류연구회, 추계 학술세미나서 공급망 회복력 논의', '<p>R물류연구회는 서울의 한 대학 국제회의장에서 ‘공급망 회복력과 물류 거점 전략’을 주제로 추계 학술세미나를 개최했다. 행사에는 학계와 업계 관계자 150여 명이 참석해 발표와 토론을 이어갔다.</p><p>발표자들은 홍해 리스크와 지정학적 변수로 운송 경로가 수시로 바뀌는 상황에서 복수 거점 운영의 필요성을 제기했다. 연구회 회장은 폐회사에서 “현장 데이터를 공유하는 산학 협력을 더욱 넓혀 가겠다”고 말했다. 연구회는 발표 내용을 담은 자료집을 연말에 발간할 예정이다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'R물류연구회는 서울의 한 대학 국제회의장에서 ‘공급망 회복력과 물류 거점 전략’을 주제로 추계 학술세미나를 개최했다. 행사에는 학계와 업계 관계자 150여 명이 참석해 발표와 토론을 이어갔다.', 'https://picsum.photos/seed/ship-people-16/800/500', '2026-08-31 10:46:00+09'::timestamptz, false),
  ('people', '[테스트] S항공물류, 전략기획 총괄 전무에 컨설팅 전문가 영입', '<p>S항공물류는 전략기획 총괄 전무로 글로벌 컨설팅사에서 물류·유통 부문을 담당해 온 전문가를 영입했다고 밝혔다. 신임 전무는 중장기 사업 전략 수립과 해외 거점 확대 업무를 맡는다.</p><p>S항공물류는 최근 동남아와 중동 지역 항공화물 수요가 늘어남에 따라 현지 법인 설립을 검토하고 있다. 회사 관계자는 “외부 시각을 반영해 사업 포트폴리오를 체계적으로 재정비할 것”이라고 설명했다. 신임 전무는 다음 달부터 본사로 출근한다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'S항공물류는 전략기획 총괄 전무로 글로벌 컨설팅사에서 물류·유통 부문을 담당해 온 전문가를 영입했다고 밝혔다. 신임 전무는 중장기 사업 전략 수립과 해외 거점 확대 업무를 맡는다.', 'https://picsum.photos/seed/ship-people-17/800/500', '2026-08-29 12:29:00+09'::timestamptz, false),
  ('people', '[테스트] T선주협의회, 신임 부회장단 선임하고 운영위원회 개편', '<p>T선주협의회는 서울에서 임시총회를 열고 벌크선사와 탱커선사, 특수선사 대표 3명을 신임 부회장으로 선임했다. 협의회는 이와 함께 운영위원회를 선종별 분과 체제로 개편하는 안건도 함께 통과시켰다.</p><p>개편된 운영위원회는 컨테이너, 벌크, 탱커, 특수선 등 4개 분과로 나뉘어 선종별 현안을 집중 논의한다. 협의회 측은 분과별 의견을 모아 국제 환경규제 대응 방안을 연말까지 정리할 예정이다. 분과별 첫 회의는 다음 달 초 차례로 열린다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'T선주협의회는 서울에서 임시총회를 열고 벌크선사와 탱커선사, 특수선사 대표 3명을 신임 부회장으로 선임했다. 협의회는 이와 함께 운영위원회를 선종별 분과 체제로 개편하는 안건도 함께 통과시켰다.', null, '2026-08-27 14:12:00+09'::timestamptz, false),
  ('people', '[테스트] U이커머스물류, 지역 대학과 물류 인재 양성 협약', '<p>U이커머스물류는 충청권의 한 국립대학과 물류 전문인력 양성을 위한 산학협력 업무협약을 체결했다고 밝혔다. 협약식은 대학 본관 회의실에서 양측 관계자 20여 명이 함께 참석한 가운데 열렸다.</p><p>양측은 협약에 따라 물류 자동화 실습 과정을 공동 개설하고 우수 학생에게 인턴십과 채용 연계 기회를 제공하기로 했다. U이커머스물류 대표는 “지역 청년이 지역 물류센터에서 성장할 수 있는 구조를 만들겠다”고 말했다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', 'U이커머스물류는 충청권의 한 국립대학과 물류 전문인력 양성을 위한 산학협력 업무협약을 체결했다고 밝혔다. 협약식은 대학 본관 회의실에서 양측 관계자 20여 명이 함께 참석한 가운데 열렸다.', 'https://picsum.photos/seed/ship-people-19/800/500', '2026-08-25 16:55:00+09'::timestamptz, false),
  ('opinion', '[테스트] [사설] 홍해 리스크 장기화, 공급망 다변화 서둘러야', '<p>홍해 항로의 불확실성이 장기화하면서 아시아와 유럽을 잇는 컨테이너 서비스의 희망봉 우회가 사실상 일상이 됐다. 운송 기간이 열흘 이상 늘어나고 운임과 보험료가 함께 오르면서 수출 기업의 부담도 누적되고 있다.</p><p>이제는 일시적 충격이 아니라 구조적 변수로 받아들이고 대응 전략을 다시 짜야 한다. 해상과 항공, 철도를 결합한 복합운송 경로를 미리 확보하고 유럽 내 거점 재고를 늘리는 등 다층적인 대비가 필요하다. 업계가 정보를 신속히 공유하는 체계도 함께 갖춰야 할 때다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '홍해 항로의 불확실성이 장기화하면서 아시아와 유럽을 잇는 컨테이너 서비스의 희망봉 우회가 사실상 일상이 됐다. 운송 기간이 열흘 이상 늘어나고 운임과 보험료가 함께 오르면서 수출 기업의 부담도 누적되고 있다.', 'https://picsum.photos/seed/ship-opinion-0/800/500', '2026-09-30 21:11:00+09'::timestamptz, true),
  ('opinion', '[테스트] [칼럼] IMO 환경규제, 중소선사의 짐을 함께 나누려면', '<p>국제 해운의 온실가스 감축 규제가 단계적으로 강화되면서 선사들의 친환경 선박 전환 압박이 커지고 있다. 대형 선사는 신조 발주로 대응하고 있지만 노후 선대를 보유한 중소선사는 투자 여력이 부족해 고민이 깊다.</p><p>규제 대응을 개별 기업의 몫으로만 남겨 두면 연안과 근해 항로의 서비스 공백으로 이어질 수 있다. 공동 연료 구매, 선박 개조 금융 지원, 운항 데이터 공유 플랫폼처럼 중소선사가 함께 활용할 수 있는 협력 모델을 적극적으로 모색해야 한다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국제 해운의 온실가스 감축 규제가 단계적으로 강화되면서 선사들의 친환경 선박 전환 압박이 커지고 있다. 대형 선사는 신조 발주로 대응하고 있지만 노후 선대를 보유한 중소선사는 투자 여력이 부족해 고민이 깊다.', 'https://picsum.photos/seed/ship-opinion-1/800/500', '2026-09-28 23:54:00+09'::timestamptz, false),
  ('opinion', '[테스트] [기고] 포워딩 디지털 전환, 데이터 표준부터 세워야', '<p>포워딩 업계에서 디지털 전환은 더 이상 선택이 아닌 생존 조건이 됐다. 그러나 현장에서는 여전히 선사와 항공사, 화주마다 서로 다른 양식의 서류와 이메일이 오가며 같은 정보를 몇 번씩 다시 입력하는 일이 반복된다.</p><p>포워딩 업체 대표로서 느끼는 가장 큰 과제는 시스템 도입보다 데이터 형식의 통일이다. 예약, 선적, 통관 정보를 공통 규격으로 주고받을 수 있어야 중소 포워더도 적은 비용으로 자동화 효과를 누릴 수 있다. 업계 공동의 표준 논의가 시급하다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '포워딩 업계에서 디지털 전환은 더 이상 선택이 아닌 생존 조건이 됐다. 그러나 현장에서는 여전히 선사와 항공사, 화주마다 서로 다른 양식의 서류와 이메일이 오가며 같은 정보를 몇 번씩 다시 입력하는 일이 반복된다.', null, '2026-09-27 01:37:00+09'::timestamptz, false),
  ('opinion', '[테스트] [사설] 부산항 신항 배후단지, 고부가가치 물류로 채워야', '<p>부산항 신항의 배후단지 조성이 속도를 내고 있지만 입주 기업의 상당수는 단순 보관과 환적 화물 처리에 머물러 있다. 넓은 부지를 확보하고도 부가가치 창출 효과가 기대에 못 미친다는 지적이 나오는 이유다.</p><p>배후단지가 제 역할을 하려면 조립, 가공, 라벨링 같은 부가 물류 기능을 갖춘 기업을 적극 유치해야 한다. 임대 조건과 인허가 절차를 유연하게 운영하고 제조와 물류가 결합된 모델을 키워 항만 경쟁력을 한 단계 끌어올리길 기대한다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '부산항 신항의 배후단지 조성이 속도를 내고 있지만 입주 기업의 상당수는 단순 보관과 환적 화물 처리에 머물러 있다. 넓은 부지를 확보하고도 부가가치 창출 효과가 기대에 못 미친다는 지적이 나오는 이유다.', 'https://picsum.photos/seed/ship-opinion-3/800/500', '2026-09-25 03:20:00+09'::timestamptz, false),
  ('opinion', '[테스트] [칼럼] 출렁이는 전자상거래 항공화물, 변동성 관리가 관건', '<p>국경 간 전자상거래 화물은 최근 몇 년간 항공화물 시장의 성장을 이끈 핵심 동력이었다. 하지만 플랫폼 정책과 각국 통관 제도 변화에 따라 물량이 단기간에 급증하거나 급감하는 일이 잦아지고 있다.</p><p>항공사와 포워더 모두 특정 물량에 대한 의존도를 점검할 시점이다. 정기 전세기 계약 비중을 조정하고 의약품, 반도체 부품 등 안정적 수요처를 함께 확보하는 포트폴리오 전략이 필요하다. 변동성은 피할 수 없지만 대비는 가능하다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '국경 간 전자상거래 화물은 최근 몇 년간 항공화물 시장의 성장을 이끈 핵심 동력이었다. 하지만 플랫폼 정책과 각국 통관 제도 변화에 따라 물량이 단기간에 급증하거나 급감하는 일이 잦아지고 있다.', 'https://picsum.photos/seed/ship-opinion-4/800/500', '2026-09-23 05:03:00+09'::timestamptz, false),
  ('opinion', '[테스트] [기고] 물류 현장 인력난, 처우 개선에서 해법 찾자', '<p>물류센터와 항만, 화물 운송 현장 곳곳에서 일할 사람을 구하기 어렵다는 목소리가 갈수록 높아지고 있다. 자동화 설비가 빠르게 늘고 있지만 여전히 많은 공정은 숙련된 인력의 손을 거쳐야 제대로 돌아간다.</p><p>현장 관리자로 일해 온 경험에 비춰 보면 인력난의 근본 원인은 임금보다 근무 환경과 성장 경로의 부재에 있다. 휴게 시설 개선, 교대 근무 합리화, 자격 취득 지원 같은 실질적 처우 개선이 함께 이뤄져야 젊은 인력이 현장에 머문다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '물류센터와 항만, 화물 운송 현장 곳곳에서 일할 사람을 구하기 어렵다는 목소리가 갈수록 높아지고 있다. 자동화 설비가 빠르게 늘고 있지만 여전히 많은 공정은 숙련된 인력의 손을 거쳐야 제대로 돌아간다.', 'https://picsum.photos/seed/ship-opinion-5/800/500', '2026-09-21 07:46:00+09'::timestamptz, false),
  ('opinion', '[테스트] [사설] 운임 급등락 시대, 장기 운송계약 문화 정착해야', '<p>컨테이너 운임이 몇 달 사이 두세 배씩 오르내리는 일이 반복되면서 화주와 선사 모두 사업 계획을 세우기 어려워졌다. 단기 현물 운임에 의존하는 거래 관행이 시장의 불안정성을 키운다는 지적도 적지 않다.</p><p>운임 지수에 연동한 장기 계약은 양측이 위험을 나누는 현실적인 대안이 될 수 있다. 선사는 안정적인 물량을, 화주는 예측 가능한 비용을 확보할 수 있기 때문이다. 표준 계약서 보급과 분쟁 조정 절차 마련으로 신뢰 기반을 넓혀야 한다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '컨테이너 운임이 몇 달 사이 두세 배씩 오르내리는 일이 반복되면서 화주와 선사 모두 사업 계획을 세우기 어려워졌다. 단기 현물 운임에 의존하는 거래 관행이 시장의 불안정성을 키운다는 지적도 적지 않다.', 'https://picsum.photos/seed/ship-opinion-6/800/500', '2026-09-19 09:29:00+09'::timestamptz, false),
  ('opinion', '[테스트] [칼럼] 친환경 선박연료 벙커링, 인프라 선점 경쟁 시작됐다', '<p>메탄올과 암모니아, 액화천연가스 등 대체 연료 추진선 발주가 늘면서 주요 항만들의 벙커링 인프라 경쟁이 본격화되고 있다. 선사들은 연료를 안정적으로 공급받을 수 있는 항만을 기항지로 우선 고려할 수밖에 없다.</p><p>연료 공급망을 갖추지 못한 항만은 장기적으로 기항 서비스 축소를 감수해야 할지도 모른다. 저장 시설과 공급선 확보, 안전 기준 정비에는 수년이 걸리는 만큼 지금부터 단계별 로드맵을 세우고 민간 투자를 끌어낼 유인책을 고민해야 한다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '메탄올과 암모니아, 액화천연가스 등 대체 연료 추진선 발주가 늘면서 주요 항만들의 벙커링 인프라 경쟁이 본격화되고 있다. 선사들은 연료를 안정적으로 공급받을 수 있는 항만을 기항지로 우선 고려할 수밖에 없다.', null, '2026-09-17 11:12:00+09'::timestamptz, false),
  ('opinion', '[테스트] [기고] 콜드체인 품질관리, 표준화가 곧 경쟁력이다', '<p>신선식품과 바이오 의약품 수요가 늘면서 콜드체인 물류는 가장 빠르게 성장하는 분야 가운데 하나가 됐다. 그러나 운송 구간마다 온도 기록 방식과 관리 기준이 달라 품질 사고의 책임 소재를 가리기 어려운 경우가 많다.</p><p>냉장 물류 기업을 운영하며 체감하는 것은 장비보다 기준의 일관성이 더 중요하다는 점이다. 출하부터 인도까지 동일한 온도 기록 규격을 적용하고 이상 발생 시 대응 절차를 공유하면 화주의 신뢰를 높이고 손실도 줄일 수 있다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '신선식품과 바이오 의약품 수요가 늘면서 콜드체인 물류는 가장 빠르게 성장하는 분야 가운데 하나가 됐다. 그러나 운송 구간마다 온도 기록 방식과 관리 기준이 달라 품질 사고의 책임 소재를 가리기 어려운 경우가 많다.', 'https://picsum.photos/seed/ship-opinion-8/800/500', '2026-09-15 13:55:00+09'::timestamptz, false),
  ('opinion', '[테스트] [사설] 중소 화주 물류비 부담, 실효성 있는 지원책 필요', '<p>운임과 창고료, 내륙 운송비가 동시에 오르면서 중소 수출기업의 물류비 부담이 한계에 이르렀다는 호소가 이어지고 있다. 대기업과 달리 물량 협상력이 약한 중소 화주는 비용 상승을 고스란히 떠안는 구조다.</p><p>공동 물류 플랫폼을 통해 소량 화물을 모아 협상력을 높이는 방안이 대안으로 거론된다. 물류비 지원 사업도 신청 절차를 간소화하고 실제 수요가 많은 품목과 항로에 집중해야 한다. 지원의 문턱을 낮추는 것이 무엇보다 중요하다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '운임과 창고료, 내륙 운송비가 동시에 오르면서 중소 수출기업의 물류비 부담이 한계에 이르렀다는 호소가 이어지고 있다. 대기업과 달리 물량 협상력이 약한 중소 화주는 비용 상승을 고스란히 떠안는 구조다.', 'https://picsum.photos/seed/ship-opinion-9/800/500', '2026-09-13 15:38:00+09'::timestamptz, false),
  ('opinion', '[테스트] [칼럼] 자율운항선박 시대, 선원 교육을 다시 설계할 때', '<p>자율운항 기술이 시험 단계를 지나 상용화 문턱에 다가서면서 선원의 역할도 빠르게 바뀌고 있다. 선박을 직접 조종하던 업무는 줄고 원격 감시와 시스템 관리, 비상 대응 역량이 더 중요해지는 흐름이다.</p><p>그럼에도 현행 교육 과정은 전통적인 항해와 기관 운용 중심에 머물러 있다. 데이터 분석과 사이버 보안, 육상 관제센터와의 협업 훈련을 교육 체계에 반영해야 한다. 기술 전환기일수록 사람에 대한 투자가 안전을 지키는 열쇠다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '자율운항 기술이 시험 단계를 지나 상용화 문턱에 다가서면서 선원의 역할도 빠르게 바뀌고 있다. 선박을 직접 조종하던 업무는 줄고 원격 감시와 시스템 관리, 비상 대응 역량이 더 중요해지는 흐름이다.', 'https://picsum.photos/seed/ship-opinion-10/800/500', '2026-09-11 17:21:00+09'::timestamptz, false),
  ('opinion', '[테스트] [기고] 통관 리스크, 선적 전 사전 점검이 비용을 줄인다', '<p>수출입 화물이 항만이나 공항에서 통관 보류로 발이 묶이면 보관료와 지체료가 하루 단위로 불어난다. 품목 분류 오류나 원산지 증빙 미비처럼 사소해 보이는 실수가 큰 손실로 이어지는 경우가 적지 않다.</p><p>통관 실무를 오래 해 온 입장에서 권하고 싶은 것은 선적 전 점검 체크리스트의 생활화다. 신규 품목은 사전 품목분류 검토를 받고 거래처별 원산지 서류를 정기적으로 갱신하면 예기치 않은 지연과 추가 비용을 상당 부분 줄일 수 있다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '수출입 화물이 항만이나 공항에서 통관 보류로 발이 묶이면 보관료와 지체료가 하루 단위로 불어난다. 품목 분류 오류나 원산지 증빙 미비처럼 사소해 보이는 실수가 큰 손실로 이어지는 경우가 적지 않다.', 'https://picsum.photos/seed/ship-opinion-11/800/500', '2026-09-09 19:04:00+09'::timestamptz, false),
  ('opinion', '[테스트] [사설] 항만 자동화, 노사 상생 모델에서 답을 찾아야', '<p>세계 주요 항만이 자동화 터미널로 전환하면서 국내 항만도 생산성 경쟁에서 뒤처지지 않기 위한 투자를 서두르고 있다. 하지만 자동화가 일자리 감소로 이어질 것이라는 현장의 불안도 함께 커지고 있다.</p><p>자동화의 성패는 기술보다 사람과의 합의에 달려 있다. 원격 조종과 장비 유지보수 같은 새 직무로의 전환 교육을 충분히 제공하고 도입 일정과 인력 운영 계획을 투명하게 공유해야 한다. 상생의 틀이 마련될 때 자동화의 효과도 온전히 살아난다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '세계 주요 항만이 자동화 터미널로 전환하면서 국내 항만도 생산성 경쟁에서 뒤처지지 않기 위한 투자를 서두르고 있다. 하지만 자동화가 일자리 감소로 이어질 것이라는 현장의 불안도 함께 커지고 있다.', null, '2026-09-07 21:47:00+09'::timestamptz, false),
  ('opinion', '[테스트] [칼럼] 북극항로, 기대와 현실 사이의 거리를 좁히려면', '<p>기후 변화로 북극해의 결빙 기간이 짧아지면서 아시아와 유럽을 잇는 북극항로에 대한 관심이 다시 높아지고 있다. 이론상 운항 거리를 크게 줄일 수 있다는 점은 분명 해운업계에 매력적인 요소다.</p><p>그러나 운항 가능한 기간이 여전히 제한적이고 내빙선 확보와 보험, 구난 체계 등 넘어야 할 과제가 많다. 환경 훼손에 대한 국제적 우려도 가볍게 볼 수 없다. 장밋빛 전망보다는 시범 운항 데이터를 차분히 축적하는 접근이 바람직하다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '기후 변화로 북극해의 결빙 기간이 짧아지면서 아시아와 유럽을 잇는 북극항로에 대한 관심이 다시 높아지고 있다. 이론상 운항 거리를 크게 줄일 수 있다는 점은 분명 해운업계에 매력적인 요소다.', 'https://picsum.photos/seed/ship-opinion-13/800/500', '2026-09-05 23:30:00+09'::timestamptz, false),
  ('opinion', '[테스트] [기고] 물류 오픈 API 생태계, 스타트업이 본 가능성', '<p>물류 스타트업을 운영하며 가장 자주 부딪히는 벽은 기술이 아니라 데이터 접근성이다. 화물 위치나 선박 입출항 정보 같은 기초 데이터를 얻기 위해 여러 기관과 기업을 일일이 접촉해야 하는 일이 다반사다.</p><p>선사와 터미널, 운송사가 기본 정보를 표준화된 오픈 API로 제공한다면 새로운 서비스가 훨씬 빠르게 등장할 수 있다. 데이터 개방은 경쟁력 유출이 아니라 생태계 전체의 파이를 키우는 일이라는 인식의 전환이 필요하다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '물류 스타트업을 운영하며 가장 자주 부딪히는 벽은 기술이 아니라 데이터 접근성이다. 화물 위치나 선박 입출항 정보 같은 기초 데이터를 얻기 위해 여러 기관과 기업을 일일이 접촉해야 하는 일이 다반사다.', 'https://picsum.photos/seed/ship-opinion-14/800/500', '2026-09-04 01:13:00+09'::timestamptz, false),
  ('opinion', '[테스트] [사설] 인천공항 화물 허브 경쟁력, 지금이 분수령이다', '<p>인천공항은 오랫동안 동북아 항공화물 허브로서 높은 위상을 지켜 왔다. 그러나 주변 공항들이 대규모 화물터미널 확장과 통관 간소화로 추격에 나서면서 지역 내 경쟁 구도가 빠르게 바뀌고 있다.</p><p>허브 경쟁력을 유지하려면 환적 화물 처리 시간을 더 단축하고 특수화물 전용 시설을 확충해야 한다. 공항 인근 물류단지와의 연계를 강화해 전자상거래와 의약품 화물을 유치하는 전략도 필요하다. 머뭇거릴 시간이 많지 않다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '인천공항은 오랫동안 동북아 항공화물 허브로서 높은 위상을 지켜 왔다. 그러나 주변 공항들이 대규모 화물터미널 확장과 통관 간소화로 추격에 나서면서 지역 내 경쟁 구도가 빠르게 바뀌고 있다.', 'https://picsum.photos/seed/ship-opinion-15/800/500', '2026-09-02 03:56:00+09'::timestamptz, false),
  ('opinion', '[테스트] [칼럼] 니어쇼어링 확산, 동남아 물류 거점 지도가 바뀐다', '<p>글로벌 제조기업들이 생산 기지를 여러 국가로 분산하는 흐름이 이어지면서 동남아 지역의 물류 수요가 빠르게 늘고 있다. 베트남과 인도네시아, 태국 등지에는 신규 공장과 함께 물류센터 투자도 잇따르고 있다.</p><p>국내 물류기업에도 기회가 열리고 있지만 현지 규제와 인력, 내륙 운송 인프라에 대한 깊은 이해가 전제돼야 한다. 단독 진출보다 현지 파트너와의 합작이나 거점 공유 방식으로 위험을 줄이며 단계적으로 네트워크를 넓히는 전략이 현실적이다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '글로벌 제조기업들이 생산 기지를 여러 국가로 분산하는 흐름이 이어지면서 동남아 지역의 물류 수요가 빠르게 늘고 있다. 베트남과 인도네시아, 태국 등지에는 신규 공장과 함께 물류센터 투자도 잇따르고 있다.', 'https://picsum.photos/seed/ship-opinion-16/800/500', '2026-08-31 05:39:00+09'::timestamptz, false),
  ('opinion', '[테스트] [기고] 탄소배출 공시 대비, 물류 데이터부터 정비하자', '<p>주요 수출 시장에서 공급망 전반의 탄소배출 정보를 요구하는 움직임이 확산되고 있다. 화주 기업들은 운송 구간별 배출량 자료를 물류 협력사에 요청하기 시작했고 그 범위도 점점 넓어지는 추세다.</p><p>해운 전문 컨설턴트로서 현장을 보면 상당수 물류기업이 연료 사용량과 운송 거리 데이터를 체계적으로 관리하지 못하고 있다. 지금부터 측정 기준을 정하고 데이터를 축적해 두지 않으면 머지않아 거래 기회 자체를 잃을 수 있다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '주요 수출 시장에서 공급망 전반의 탄소배출 정보를 요구하는 움직임이 확산되고 있다. 화주 기업들은 운송 구간별 배출량 자료를 물류 협력사에 요청하기 시작했고 그 범위도 점점 넓어지는 추세다.', null, '2026-08-29 07:22:00+09'::timestamptz, false),
  ('opinion', '[테스트] [사설] 물류 현장 안전, 예방 투자를 아끼지 말아야', '<p>물류센터와 항만 하역 현장에서 크고 작은 안전사고가 좀처럼 끊이지 않고 있다. 지게차 충돌, 화물 낙하, 고온 작업 환경 등 주요 위험 요인은 이미 잘 알려져 있지만 현장의 개선 속도는 여전히 더디다.</p><p>안전은 비용이 아니라 지속 가능한 사업의 전제 조건이다. 충돌 방지 센서와 작업 구역 분리 같은 기본 설비 투자를 서두르고, 협력업체와 일용직 근로자까지 포함하는 안전 교육 체계를 갖춰야 한다. 사고가 난 뒤의 대책은 언제나 늦다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '물류센터와 항만 하역 현장에서 크고 작은 안전사고가 좀처럼 끊이지 않고 있다. 지게차 충돌, 화물 낙하, 고온 작업 환경 등 주요 위험 요인은 이미 잘 알려져 있지만 현장의 개선 속도는 여전히 더디다.', 'https://picsum.photos/seed/ship-opinion-18/800/500', '2026-08-27 09:05:00+09'::timestamptz, false),
  ('opinion', '[테스트] [칼럼] 해운 금융 다변화, 선박 투자 생태계를 넓히자', '<p>친환경 선박 전환과 노후선 교체 수요가 겹치면서 해운업계의 자금 수요가 크게 늘고 있다. 그러나 선박 금융은 여전히 소수 금융기관에 의존하는 구조여서 중소선사의 자금 조달 문턱이 높다.</p><p>선박 투자 펀드와 녹색 채권, 리스 금융 등 조달 수단을 다양화해 민간 자본의 참여를 넓혀야 한다. 친환경 선박에 대한 금리 우대나 위험 분담 장치를 마련한다면 투자자와 선사 모두에게 매력적인 시장이 될 수 있다. 해운의 체질 개선은 자금의 물꼬를 트는 데서 시작된다.</p><p><em>※ 홈페이지 테스트용 가상 기사입니다. 등장하는 회사·기관·인물·수치는 실제와 관계없습니다.</em></p>', '친환경 선박 전환과 노후선 교체 수요가 겹치면서 해운업계의 자금 수요가 크게 늘고 있다. 그러나 선박 금융은 여전히 소수 금융기관에 의존하는 구조여서 중소선사의 자금 조달 문턱이 높다.', 'https://picsum.photos/seed/ship-opinion-19/800/500', '2026-08-25 11:48:00+09'::timestamptz, false)
) as v(slug, title, body, excerpt, thumb, published_at, featured)
join categories c on c.outlet_id = ctx.outlet_id and c.slug = v.slug
where ctx.author_id is not null
  and not exists (select 1 from articles a where a.outlet_id = ctx.outlet_id and a.title = v.title);

