-- 확인
select c.name as "섹션", count(a.id) as "기사 수"
from categories c join outlets o on o.id = c.outlet_id
left join articles a on a.category_id = c.id and a.title like '[테스트]%'
where o.name = 'Shipping Times' group by c.name, c.sort_order order by c.sort_order;
